FILES = {'.env.example': '# ════════════════════════════════════════════════════════\n#   Yuvorai — Environment Variables\n#   Render Dashboard mein ye sab add karo (Variables tab)\n# ════════════════════════════════════════════════════════\n\n# ── REQUIRED ─────────────────────────────────────────────\nTELEGRAM_BOT_TOKEN=your_bot_token_here\nOPENAI_API_KEY=sk-your_openai_key_here\nADMIN_TELEGRAM_IDS=[your_telegram_id]\n\n# ── AUTO-SET BY RENDER (manually bhi dal sakte ho) ───────\n# Render automatically set karta hai — looks like:\n# https://yuvorai-bot.onrender.com\nRENDER_EXTERNAL_URL=https://your-service-name.onrender.com\n\n# ── OPTIONAL ─────────────────────────────────────────────\nAPP_ENV=production\nOPENAI_MODEL=gpt-4o-mini\nDAILY_ALERT_HOUR=9\nDAILY_ALERT_MINUTE=0\nMAX_FREE_OPPORTUNITIES=3\nMAX_FREE_AI_MESSAGES=5\nPRICE_STARTER=5\nPRICE_GROWTH=10\nPRICE_ELITE=49\nREFERRAL_REWARD_DAYS=7\n', '.gitignore': '# ── Secrets — KABHI COMMIT MAT KARO ──────────────────────\n.env\n*.env\n.env.*\n!.env.example\n\n# ── Database ──────────────────────────────────────────────\n*.db\n*.sqlite\n*.sqlite3\n/data/\n\n# ── Python ────────────────────────────────────────────────\n__pycache__/\n*.py[cod]\n*.pyo\n*.egg-info/\ndist/\nbuild/\n.eggs/\nvenv/\nenv/\n.venv/\n\n# ── IDE ───────────────────────────────────────────────────\n.idea/\n.vscode/\n.DS_Store\n*.swp\n\n# ── Logs ──────────────────────────────────────────────────\n*.log\nlogs/\n', 'Procfile': '# Yuvorai — Procfile\nweb: uvicorn main:web --host 0.0.0.0 --port $PORT\n', 'config.py': '"""\nYuvorai — Configuration\nAll settings read from environment variables.\n"""\n\nimport os\nfrom pydantic_settings import BaseSettings\nfrom functools import lru_cache\n\n\ndef _default_db_url() -> str:\n    # Use /data volume on Render/Railway if available\n    if os.path.exists("/data"):\n        return "sqlite+aiosqlite:////data/yuvorai.db"\n    return "sqlite+aiosqlite:///./yuvorai.db"\n\n\nclass Settings(BaseSettings):\n    # ── Telegram ──────────────────────────────────────────────────────────\n    TELEGRAM_BOT_TOKEN: str\n    ADMIN_TELEGRAM_IDS: list[int] = []\n\n    # ── Render ────────────────────────────────────────────────────────────\n    # Auto-set by Render — looks like: https://yuvorai-bot.onrender.com\n    RENDER_EXTERNAL_URL: str = ""\n    PORT: int = 8000\n\n    # ── Database ──────────────────────────────────────────────────────────\n    DATABASE_URL: str = _default_db_url()\n\n    # ── OpenAI ────────────────────────────────────────────────────────────\n    OPENAI_API_KEY: str\n    OPENAI_MODEL: str = "gpt-4o-mini"\n\n    # ── App ───────────────────────────────────────────────────────────────\n    APP_ENV: str = "production"\n    DAILY_ALERT_HOUR: int = 9\n    DAILY_ALERT_MINUTE: int = 0\n    MAX_FREE_OPPORTUNITIES: int = 3\n    MAX_FREE_AI_MESSAGES: int = 5\n\n    # ── Premium pricing (INR) ─────────────────────────────────────────────\n    PRICE_STARTER: int = 5\n    PRICE_GROWTH: int = 10\n    PRICE_ELITE: int = 49\n\n    # ── Referral ──────────────────────────────────────────────────────────\n    REFERRAL_REWARD_DAYS: int = 7\n\n    class Config:\n        env_file = ".env"\n        env_file_encoding = "utf-8"\n\n\n@lru_cache\ndef get_settings() -> Settings:\n    return Settings()\n\n\nsettings = get_settings()\n', 'main.py': '"""\nYuvorai — Main Entry Point (Render Deployment)\nUses WEBHOOK mode on Render for 24/7 operation.\n  - Telegram sends updates to our HTTPS URL (no polling needed)\n  - FastAPI serves the webhook + /health endpoint (keeps Render alive)\n  - APScheduler runs daily alerts even in webhook mode\n  - UptimeRobot pings /health every 5 min → bot stays awake 24/7\n"""\n\nimport asyncio\nimport logging\nimport os\n\nfrom fastapi import FastAPI, Request, Response\nfrom telegram import Update\nfrom telegram.ext import (\n    Application,\n    CommandHandler,\n    MessageHandler,\n    CallbackQueryHandler,\n    filters,\n)\n\nfrom config import settings\nfrom database.db import init_db\nfrom handlers.onboarding import onboarding_conv_handler\nfrom handlers.opportunities import cmd_opportunities, handle_opportunity_callback\nfrom handlers.career_assistant import cmd_ask, cmd_end_chat, handle_ai_message\nfrom handlers.networking import cmd_networking, handle_networking_callback\nfrom handlers.pods import cmd_pods, handle_pods_callback\nfrom handlers.referral import cmd_referral, handle_referral_callback\nfrom handlers.premium import cmd_premium, handle_premium_callback\nfrom handlers.admin import cmd_admin, handle_admin_callback, handle_admin_message\nfrom handlers.profile import cmd_profile, cmd_edit_profile\nfrom handlers.help import cmd_help, handle_help_callback, set_bot_commands\nfrom handlers.error_handler import error_handler\nfrom services.alert_service import schedule_daily_alerts\n\nlogging.basicConfig(\n    format="%(asctime)s | %(levelname)s | %(name)s | %(message)s",\n    level=logging.INFO,\n)\nlogger = logging.getLogger(__name__)\n\n# ── FastAPI app ───────────────────────────────────────────────────────────────\nweb = FastAPI()\n\n# ── Telegram Application (built once, reused) ─────────────────────────────────\n_tg_app: Application | None = None\n\n\ndef _build_telegram_app() -> Application:\n    app = Application.builder().token(settings.TELEGRAM_BOT_TOKEN).build()\n\n    app.add_handler(onboarding_conv_handler())\n\n    app.add_handler(CommandHandler("opportunities", cmd_opportunities))\n    app.add_handler(CommandHandler("pods",          cmd_pods))\n    app.add_handler(CommandHandler("networking",    cmd_networking))\n    app.add_handler(CommandHandler("referral",      cmd_referral))\n    app.add_handler(CommandHandler("premium",       cmd_premium))\n    app.add_handler(CommandHandler("profile",       cmd_profile))\n    app.add_handler(CommandHandler("editprofile",   cmd_edit_profile))\n    app.add_handler(CommandHandler("admin",         cmd_admin))\n    app.add_handler(CommandHandler("ask",           cmd_ask))\n    app.add_handler(CommandHandler("endchat",       cmd_end_chat))\n    app.add_handler(CommandHandler("help",          cmd_help))\n\n    app.add_handler(CallbackQueryHandler(handle_opportunity_callback, pattern=r"^opp_"))\n    app.add_handler(CallbackQueryHandler(handle_pods_callback,        pattern=r"^pod_"))\n    app.add_handler(CallbackQueryHandler(handle_networking_callback,  pattern=r"^net_"))\n    app.add_handler(CallbackQueryHandler(handle_referral_callback,    pattern=r"^ref_"))\n    app.add_handler(CallbackQueryHandler(handle_premium_callback,     pattern=r"^prem_"))\n    app.add_handler(CallbackQueryHandler(handle_admin_callback,       pattern=r"^adm_"))\n    app.add_handler(CallbackQueryHandler(handle_help_callback,        pattern=r"^help_"))\n\n    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _smart_router))\n    app.add_error_handler(error_handler)\n\n    return app\n\n\nasync def _smart_router(update, ctx):\n    from handlers.admin import handle_admin_message, _admin_state\n    from handlers.career_assistant import handle_ai_message\n    tg_id = update.effective_user.id\n    if tg_id in _admin_state:\n        await handle_admin_message(update, ctx)\n    else:\n        await handle_ai_message(update, ctx)\n\n\n# ── FastAPI lifecycle ─────────────────────────────────────────────────────────\n\n@web.on_event("startup")\nasync def on_startup():\n    global _tg_app\n\n    # Init DB\n    await init_db()\n    logger.info("✅ Database initialized.")\n\n    # Build & start Telegram app (webhook mode)\n    _tg_app = _build_telegram_app()\n    await _tg_app.initialize()\n    await _tg_app.start()\n\n    # Register bot commands in Telegram menu\n    await set_bot_commands(_tg_app)\n    logger.info("✅ Bot commands registered.")\n\n    # Set Telegram webhook to our Render URL\n    webhook_url = f"{settings.RENDER_EXTERNAL_URL}/telegram/webhook"\n    await _tg_app.bot.set_webhook(\n        url=webhook_url,\n        allowed_updates=["message", "callback_query"],\n        drop_pending_updates=True,\n    )\n    logger.info(f"✅ Webhook set: {webhook_url}")\n\n    # Start daily alert scheduler in background\n    asyncio.create_task(schedule_daily_alerts(_tg_app.bot))\n    logger.info("✅ Daily alert scheduler started.")\n\n    logger.info("🚀 Yuvorai is LIVE on Render!")\n\n\n@web.on_event("shutdown")\nasync def on_shutdown():\n    if _tg_app:\n        await _tg_app.bot.delete_webhook()\n        await _tg_app.stop()\n        await _tg_app.shutdown()\n    logger.info("🛑 Yuvorai shutdown.")\n\n\n# ── Routes ────────────────────────────────────────────────────────────────────\n\n@web.post("/telegram/webhook")\nasync def telegram_webhook(request: Request):\n    """Receives all Telegram updates via webhook."""\n    if _tg_app is None:\n        return Response(status_code=503)\n    data = await request.json()\n    update = Update.de_json(data, _tg_app.bot)\n    await _tg_app.process_update(update)\n    return Response(status_code=200)\n\n\n@web.get("/health")\nasync def health_check():\n    """\n    UptimeRobot pings this every 5 min → Render stays awake 24/7.\n    Returns bot status.\n    """\n    bot_ok = _tg_app is not None and _tg_app.running\n    return {\n        "status":  "ok" if bot_ok else "starting",\n        "bot":     "running" if bot_ok else "initializing",\n        "service": "Yuvorai AI Career Bot",\n    }\n\n\n@web.get("/")\nasync def root():\n    return {"message": "Yuvorai Bot is running! Use Telegram to interact."}\n', 'render.yaml': '# Yuvorai — Render Deployment Config\n# render.yaml — auto-detected by Render\n\nservices:\n  - type: web\n    name: yuvorai-bot\n    runtime: python\n    buildCommand: pip install -r requirements.txt\n    startCommand: uvicorn main:web --host 0.0.0.0 --port $PORT\n    healthCheckPath: /health\n\n    # Free tier (set to starter for always-on)\n    plan: free\n\n    envVars:\n      - key: TELEGRAM_BOT_TOKEN\n        sync: false   # Set manually in Render dashboard\n\n      - key: OPENAI_API_KEY\n        sync: false\n\n      - key: ADMIN_TELEGRAM_IDS\n        sync: false\n\n      - key: RENDER_EXTERNAL_URL\n        fromService:\n          type: web\n          name: yuvorai-bot\n          property: host\n\n      - key: APP_ENV\n        value: production\n\n      - key: OPENAI_MODEL\n        value: gpt-4o-mini\n\n      - key: DAILY_ALERT_HOUR\n        value: "9"\n\n      - key: MAX_FREE_AI_MESSAGES\n        value: "5"\n\n    disk:\n      name: yuvorai-data\n      mountPath: /data\n      sizeGB: 1\n', 'requirements.txt': '# Yuvorai — Dependencies (Render deployment)\n\n# ── Telegram Bot ──────────────────────────────────────────────────────────────\npython-telegram-bot==21.5\n\n# ── Web Server (Webhook + Health check for Render) ────────────────────────────\nfastapi==0.115.0\nuvicorn[standard]==0.30.6\n\n# ── Database ──────────────────────────────────────────────────────────────────\nsqlalchemy==2.0.35\naiosqlite==0.20.0\n\n# ── AI ────────────────────────────────────────────────────────────────────────\nopenai==1.51.0\n\n# ── HTTP ──────────────────────────────────────────────────────────────────────\nhttpx==0.27.2\n\n# ── Config ────────────────────────────────────────────────────────────────────\npydantic==2.9.2\npydantic-settings==2.5.2\npython-dotenv==1.0.1\n', 'database/__init__.py': '', 'database/db.py': '"""\nYuvorai — Database Connection\nProvides async SQLAlchemy engine + session factory.\n"""\n\nfrom __future__ import annotations\n\nfrom contextlib import asynccontextmanager\nfrom typing import AsyncGenerator\n\nfrom sqlalchemy.ext.asyncio import (\n    AsyncSession,\n    async_sessionmaker,\n    create_async_engine,\n)\n\nfrom config import settings\nfrom database.models import Base\n\n# ── Engine ────────────────────────────────────────────────────────────────────\n\nengine = create_async_engine(\n    settings.DATABASE_URL,\n    echo=settings.APP_ENV == "development",\n    pool_pre_ping=True,\n)\n\nAsyncSessionLocal = async_sessionmaker(\n    bind=engine,\n    class_=AsyncSession,\n    expire_on_commit=False,\n    autocommit=False,\n    autoflush=False,\n)\n\n\n# ── Init ──────────────────────────────────────────────────────────────────────\n\nasync def init_db() -> None:\n    """Create all tables (if they don\'t exist) and seed default pods."""\n    async with engine.begin() as conn:\n        await conn.run_sync(Base.metadata.create_all)\n    await _seed_default_pods()\n\n\nasync def _seed_default_pods() -> None:\n    """Create default Peer Pods on first run."""\n    from database.models import Pod, PremiumPlan\n\n    default_pods = [\n        {"name": "AI Beginners 🤖",         "emoji": "🤖", "description": "Learn AI/ML together — zero to hero.", "tags": ["AI", "ML"]},\n        {"name": "Placement Prep 🎯",        "emoji": "🎯", "description": "Crack campus placements together.", "tags": ["Placement", "DSA"]},\n        {"name": "DSA Grind ⚡",             "emoji": "⚡", "description": "Daily LeetCode & problem-solving.", "tags": ["DSA", "Competitive"], "min_plan": PremiumPlan.GROWTH},\n        {"name": "Startup Builders 🏗️",     "emoji": "🏗️", "description": "Build your first startup — find co-founders.", "tags": ["Startup", "Entrepreneurship"], "min_plan": PremiumPlan.GROWTH},\n        {"name": "Hackathon Squad 🏆",       "emoji": "🏆", "description": "Form teams & win hackathons.", "tags": ["Hackathon", "Team"]},\n        {"name": "Web Dev Hub 🌐",           "emoji": "🌐", "description": "HTML to full-stack — build together.", "tags": ["Web Dev", "Frontend", "Backend"]},\n        {"name": "Open Source Crew 🌍",      "emoji": "🌍", "description": "GSoC, Outreachy, and beyond.", "tags": ["Open Source", "GSoC"], "min_plan": PremiumPlan.GROWTH},\n        {"name": "Elite Career Circle 💎",   "emoji": "💎", "description": "Exclusive mentorship & accountability.", "tags": ["Elite", "Mentorship"], "min_plan": PremiumPlan.ELITE},\n    ]\n\n    async with AsyncSessionLocal() as session:\n        from sqlalchemy import select\n        for pod_data in default_pods:\n            result = await session.execute(\n                select(Pod).where(Pod.name == pod_data["name"])\n            )\n            if not result.scalar_one_or_none():\n                pod = Pod(\n                    name=pod_data["name"],\n                    emoji=pod_data["emoji"],\n                    description=pod_data["description"],\n                    tags=pod_data.get("tags", []),\n                    min_plan=pod_data.get("min_plan", PremiumPlan.FREE),\n                )\n                session.add(pod)\n        await session.commit()\n\n\n# ── Session context manager ───────────────────────────────────────────────────\n\n@asynccontextmanager\nasync def get_session() -> AsyncGenerator[AsyncSession, None]:\n    async with AsyncSessionLocal() as session:\n        try:\n            yield session\n            await session.commit()\n        except Exception:\n            await session.rollback()\n            raise\n', 'database/models.py': '"""\nYuvorai — Database Models\nUses SQLAlchemy 2.x async ORM with SQLite (dev) / PostgreSQL (prod).\n"""\n\nfrom __future__ import annotations\n\nimport enum\nfrom datetime import datetime, date\nfrom typing import Optional, List\n\nfrom sqlalchemy import (\n    BigInteger, Boolean, DateTime, Enum as SAEnum,\n    ForeignKey, Integer, String, Text, Date, JSON,\n    UniqueConstraint, func,\n)\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Enums\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass SkillLevel(str, enum.Enum):\n    BEGINNER     = "beginner"\n    INTERMEDIATE = "intermediate"\n    ADVANCED     = "advanced"\n\n\nclass PremiumPlan(str, enum.Enum):\n    FREE    = "free"\n    STARTER = "starter"\n    GROWTH  = "growth"\n    ELITE   = "elite"\n\n\nclass OpportunityType(str, enum.Enum):\n    INTERNSHIP  = "internship"\n    HACKATHON   = "hackathon"\n    CONTEST     = "contest"\n    SCHOLARSHIP = "scholarship"\n    OPEN_SOURCE = "open_source"\n    STARTUP     = "startup"\n    PLACEMENT   = "placement"\n    OTHER       = "other"\n\n\nclass DifficultyLevel(str, enum.Enum):\n    BEGINNER     = "beginner"\n    INTERMEDIATE = "intermediate"\n    ADVANCED     = "advanced"\n\n\nclass AlertType(str, enum.Enum):\n    OPPORTUNITY   = "opportunity"\n    DEADLINE      = "deadline"\n    SYSTEM        = "system"\n    MOTIVATIONAL  = "motivational"\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Base\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass Base(DeclarativeBase):\n    pass\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# User\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass User(Base):\n    __tablename__ = "users"\n\n    id: Mapped[int]             = mapped_column(Integer, primary_key=True, autoincrement=True)\n    telegram_id: Mapped[int]    = mapped_column(BigInteger, unique=True, nullable=False, index=True)\n    username: Mapped[Optional[str]] = mapped_column(String(64))\n    name: Mapped[str]           = mapped_column(String(128), nullable=False)\n    college: Mapped[str]        = mapped_column(String(256), nullable=False)\n    branch: Mapped[str]         = mapped_column(String(128), nullable=False)\n    year: Mapped[int]           = mapped_column(Integer, nullable=False)\n    interests: Mapped[list]     = mapped_column(JSON, default=list)   # ["AI", "Web Dev", ...]\n    goals: Mapped[list]         = mapped_column(JSON, default=list)   # ["Internships", ...]\n    skill_level: Mapped[SkillLevel] = mapped_column(\n        SAEnum(SkillLevel), default=SkillLevel.BEGINNER\n    )\n    premium_plan: Mapped[PremiumPlan] = mapped_column(\n        SAEnum(PremiumPlan), default=PremiumPlan.FREE\n    )\n    premium_expires_at: Mapped[Optional[datetime]] = mapped_column(DateTime)\n    is_admin: Mapped[bool]      = mapped_column(Boolean, default=False)\n    is_active: Mapped[bool]     = mapped_column(Boolean, default=True)\n    alerts_enabled: Mapped[bool] = mapped_column(Boolean, default=True)\n    referral_code: Mapped[str]  = mapped_column(String(16), unique=True)\n    referred_by: Mapped[Optional[int]] = mapped_column(\n        BigInteger, ForeignKey("users.telegram_id"), nullable=True\n    )\n    daily_ai_messages: Mapped[int] = mapped_column(Integer, default=0)\n    ai_messages_reset_date: Mapped[Optional[date]] = mapped_column(Date)\n    onboarding_complete: Mapped[bool] = mapped_column(Boolean, default=False)\n    ai_chat_active: Mapped[bool] = mapped_column(Boolean, default=False)\n    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n    updated_at: Mapped[datetime] = mapped_column(\n        DateTime, server_default=func.now(), onupdate=func.now()\n    )\n\n    # relationships\n    pod_memberships: Mapped[List["PodMembership"]]  = relationship(back_populates="user")\n    applications: Mapped[List["Application"]]       = relationship(back_populates="user")\n    alerts_sent: Mapped[List["AlertLog"]]           = relationship(back_populates="user")\n    referrals: Mapped[List["Referral"]]             = relationship(\n        "Referral", foreign_keys="[Referral.referrer_id]", back_populates="referrer"\n    )\n\n    def __repr__(self) -> str:\n        return f"<User telegram_id={self.telegram_id} name={self.name}>"\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Opportunity\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass Opportunity(Base):\n    __tablename__ = "opportunities"\n\n    id: Mapped[int]             = mapped_column(Integer, primary_key=True, autoincrement=True)\n    title: Mapped[str]          = mapped_column(String(256), nullable=False)\n    summary: Mapped[str]        = mapped_column(Text, nullable=False)\n    description: Mapped[Optional[str]] = mapped_column(Text)\n    type: Mapped[OpportunityType] = mapped_column(SAEnum(OpportunityType), index=True)\n    difficulty: Mapped[DifficultyLevel] = mapped_column(\n        SAEnum(DifficultyLevel), default=DifficultyLevel.BEGINNER\n    )\n    is_beginner_friendly: Mapped[bool] = mapped_column(Boolean, default=False)\n    is_low_competition: Mapped[bool]   = mapped_column(Boolean, default=False)\n    is_verified: Mapped[bool]          = mapped_column(Boolean, default=False)\n    is_active: Mapped[bool]            = mapped_column(Boolean, default=True)\n    eligibility: Mapped[Optional[str]] = mapped_column(Text)\n    tags: Mapped[list]          = mapped_column(JSON, default=list)   # ["AI", "Python", ...]\n    target_branches: Mapped[list] = mapped_column(JSON, default=list) # [] = all branches\n    target_years: Mapped[list]  = mapped_column(JSON, default=list)   # [] = all years\n    min_skill_level: Mapped[SkillLevel] = mapped_column(\n        SAEnum(SkillLevel), default=SkillLevel.BEGINNER\n    )\n    apply_link: Mapped[str]     = mapped_column(String(1024), nullable=False)\n    source: Mapped[Optional[str]] = mapped_column(String(256))\n    deadline: Mapped[Optional[date]] = mapped_column(Date, index=True)\n    ai_relevance_score: Mapped[float] = mapped_column(Integer, default=0)\n    view_count: Mapped[int]     = mapped_column(Integer, default=0)\n    apply_count: Mapped[int]    = mapped_column(Integer, default=0)\n    added_by: Mapped[Optional[int]] = mapped_column(BigInteger)  # admin telegram_id\n    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    # relationships\n    applications: Mapped[List["Application"]] = relationship(back_populates="opportunity")\n\n    def __repr__(self) -> str:\n        return f"<Opportunity id={self.id} title={self.title[:40]}>"\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Application (user → opportunity click/apply tracking)\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass Application(Base):\n    __tablename__ = "applications"\n    __table_args__ = (UniqueConstraint("user_id", "opportunity_id"),)\n\n    id: Mapped[int]             = mapped_column(Integer, primary_key=True, autoincrement=True)\n    user_id: Mapped[int]        = mapped_column(ForeignKey("users.id"), index=True)\n    opportunity_id: Mapped[int] = mapped_column(ForeignKey("opportunities.id"), index=True)\n    clicked_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    user: Mapped["User"]               = relationship(back_populates="applications")\n    opportunity: Mapped["Opportunity"] = relationship(back_populates="applications")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Peer Pods\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass Pod(Base):\n    __tablename__ = "pods"\n\n    id: Mapped[int]         = mapped_column(Integer, primary_key=True, autoincrement=True)\n    name: Mapped[str]       = mapped_column(String(128), unique=True, nullable=False)\n    description: Mapped[str] = mapped_column(Text)\n    emoji: Mapped[str]      = mapped_column(String(8), default="🚀")\n    tags: Mapped[list]      = mapped_column(JSON, default=list)\n    telegram_invite_link: Mapped[Optional[str]] = mapped_column(String(256))\n    member_count: Mapped[int] = mapped_column(Integer, default=0)\n    min_plan: Mapped[PremiumPlan] = mapped_column(\n        SAEnum(PremiumPlan), default=PremiumPlan.FREE\n    )\n    is_active: Mapped[bool] = mapped_column(Boolean, default=True)\n    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    memberships: Mapped[List["PodMembership"]] = relationship(back_populates="pod")\n\n\nclass PodMembership(Base):\n    __tablename__ = "pod_memberships"\n    __table_args__ = (UniqueConstraint("user_id", "pod_id"),)\n\n    id: Mapped[int]     = mapped_column(Integer, primary_key=True, autoincrement=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey("users.id"), index=True)\n    pod_id: Mapped[int] = mapped_column(ForeignKey("pods.id"), index=True)\n    joined_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    user: Mapped["User"] = relationship(back_populates="pod_memberships")\n    pod: Mapped["Pod"]   = relationship(back_populates="memberships")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Referral\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass Referral(Base):\n    __tablename__ = "referrals"\n\n    id: Mapped[int]           = mapped_column(Integer, primary_key=True, autoincrement=True)\n    referrer_id: Mapped[int]  = mapped_column(\n        ForeignKey("users.id"), index=True\n    )\n    referee_telegram_id: Mapped[int] = mapped_column(BigInteger, unique=True)\n    reward_granted: Mapped[bool] = mapped_column(Boolean, default=False)\n    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    referrer: Mapped["User"] = relationship(\n        "User", foreign_keys=[referrer_id], back_populates="referrals"\n    )\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Alert Log  (prevent duplicate alerts)\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass AlertLog(Base):\n    __tablename__ = "alert_logs"\n\n    id: Mapped[int]         = mapped_column(Integer, primary_key=True, autoincrement=True)\n    user_id: Mapped[int]    = mapped_column(ForeignKey("users.id"), index=True)\n    alert_type: Mapped[AlertType] = mapped_column(SAEnum(AlertType))\n    reference_id: Mapped[Optional[int]] = mapped_column(Integer)  # opportunity id etc.\n    sent_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())\n\n    user: Mapped["User"] = relationship(back_populates="alerts_sent")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Analytics Event\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass AnalyticsEvent(Base):\n    __tablename__ = "analytics_events"\n\n    id: Mapped[int]           = mapped_column(Integer, primary_key=True, autoincrement=True)\n    telegram_id: Mapped[int]  = mapped_column(BigInteger, index=True)\n    event_name: Mapped[str]   = mapped_column(String(64), index=True)\n    event_data: Mapped[Optional[dict]] = mapped_column(JSON)\n    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now(), index=True)\n', 'handlers/__init__.py': '', 'handlers/admin.py': '"""\nYuvorai — Admin Handler\nFull admin panel: add opportunities, broadcast, manage users, view analytics.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom datetime import date, datetime\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select, func\n\nfrom database.db import get_session\nfrom database.models import (\n    User, Opportunity, Pod, PremiumPlan,\n    OpportunityType, DifficultyLevel, SkillLevel, AnalyticsEvent,\n)\nfrom services.ai_engine import classify_opportunity\nfrom services.analytics import track_event\nfrom config import settings\n\nlogger = logging.getLogger(__name__)\n\n# Admin state storage (in-memory for simplicity)\n_admin_state: dict[int, dict] = {}\n\n\ndef is_admin(tg_id: int) -> bool:\n    return tg_id in settings.ADMIN_TELEGRAM_IDS\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# /admin  —  Admin Dashboard\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def cmd_admin(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    if not is_admin(tg_id):\n        await update.message.reply_text("⛔ Unauthorised.")\n        return\n\n    async with get_session() as session:\n        user_count  = (await session.execute(select(func.count(User.id)))).scalar()\n        opp_count   = (await session.execute(select(func.count(Opportunity.id)))).scalar()\n        active_users = (await session.execute(\n            select(func.count(User.id)).where(User.is_active == True)\n        )).scalar()\n        premium_users = (await session.execute(\n            select(func.count(User.id)).where(User.premium_plan != PremiumPlan.FREE)\n        )).scalar()\n\n    kb = InlineKeyboardMarkup([\n        [InlineKeyboardButton("➕ Add Opportunity",   callback_data="adm_add_opp")],\n        [InlineKeyboardButton("✅ Verify Pending",    callback_data="adm_verify_opps")],\n        [InlineKeyboardButton("📢 Broadcast Message", callback_data="adm_broadcast")],\n        [InlineKeyboardButton("👥 Manage Users",      callback_data="adm_users")],\n        [InlineKeyboardButton("📊 Analytics",         callback_data="adm_analytics")],\n        [InlineKeyboardButton("🏘️ Manage Pods",       callback_data="adm_pods")],\n    ])\n\n    await update.message.reply_text(\n        f"🛠 *Yuvorai Admin Panel*\\n\\n"\n        f"📈 *Stats:*\\n"\n        f"• Total users: *{user_count}*\\n"\n        f"• Active users: *{active_users}*\\n"\n        f"• Premium users: *{premium_users}*\\n"\n        f"• Total opportunities: *{opp_count}*\\n\\n"\n        "Choose an action 👇",\n        parse_mode="Markdown",\n        reply_markup=kb,\n    )\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Admin Callbacks\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def handle_admin_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n\n    if not is_admin(tg_id):\n        await query.answer("⛔ Unauthorised", show_alert=True)\n        return\n\n    data = query.data\n\n    # ── Add Opportunity ───────────────────────────────────────────────────\n    if data == "adm_add_opp":\n        _admin_state[tg_id] = {"action": "add_opp", "step": "title"}\n        await query.message.reply_text(\n            "➕ *Add New Opportunity*\\n\\nStep 1/6 — Send the *title* of the opportunity:",\n            parse_mode="Markdown",\n        )\n\n    # ── Verify Pending ────────────────────────────────────────────────────\n    elif data == "adm_verify_opps":\n        async with get_session() as session:\n            res = await session.execute(\n                select(Opportunity).where(Opportunity.is_verified == False).limit(5)\n            )\n            pending = res.scalars().all()\n\n        if not pending:\n            await query.message.reply_text("✅ No pending opportunities to verify!")\n            return\n\n        for opp in pending:\n            kb = InlineKeyboardMarkup([[\n                InlineKeyboardButton("✅ Verify",  callback_data=f"adm_vfy_{opp.id}"),\n                InlineKeyboardButton("🗑 Delete",  callback_data=f"adm_del_{opp.id}"),\n            ]])\n            await query.message.reply_text(\n                f"*{opp.title}*\\n{opp.summary[:200]}\\n🔗 {opp.apply_link}",\n                parse_mode="Markdown",\n                reply_markup=kb,\n            )\n\n    elif data.startswith("adm_vfy_"):\n        opp_id = int(data.split("_")[-1])\n        async with get_session() as session:\n            res = await session.execute(select(Opportunity).where(Opportunity.id == opp_id))\n            opp = res.scalar_one_or_none()\n            if opp:\n                opp.is_verified = True\n        await query.answer("✅ Opportunity verified!", show_alert=True)\n\n    elif data.startswith("adm_del_"):\n        opp_id = int(data.split("_")[-1])\n        async with get_session() as session:\n            res = await session.execute(select(Opportunity).where(Opportunity.id == opp_id))\n            opp = res.scalar_one_or_none()\n            if opp:\n                opp.is_active = False\n        await query.answer("🗑 Opportunity removed.", show_alert=True)\n\n    # ── Broadcast ─────────────────────────────────────────────────────────\n    elif data == "adm_broadcast":\n        _admin_state[tg_id] = {"action": "broadcast"}\n        await query.message.reply_text(\n            "📢 *Broadcast Message*\\n\\nSend the message you want to broadcast to ALL active users.\\n"\n            "_Supports Markdown formatting._\\n\\nType your message now:",\n            parse_mode="Markdown",\n        )\n\n    # ── Analytics ─────────────────────────────────────────────────────────\n    elif data == "adm_analytics":\n        await _show_analytics(query)\n\n    # ── Users ─────────────────────────────────────────────────────────────\n    elif data == "adm_users":\n        await _show_users(query)\n\n    # ── Pods ──────────────────────────────────────────────────────────────\n    elif data == "adm_pods":\n        async with get_session() as session:\n            res = await session.execute(select(Pod))\n            pods = res.scalars().all()\n\n        text = "🏘️ *Pods Overview*\\n\\n"\n        for pod in pods:\n            text += f"{pod.emoji} {pod.name} — {pod.member_count} members\\n"\n        await query.message.reply_text(text, parse_mode="Markdown")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Admin free-text handler (multi-step flows)\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def handle_admin_message(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    if not is_admin(tg_id) or tg_id not in _admin_state:\n        return\n\n    state  = _admin_state[tg_id]\n    action = state.get("action")\n    text   = update.message.text.strip()\n\n    # ── Broadcast flow ────────────────────────────────────────────────────\n    if action == "broadcast":\n        async with get_session() as session:\n            res = await session.execute(\n                select(User.telegram_id).where(User.is_active == True, User.alerts_enabled == True)\n            )\n            tg_ids = [row[0] for row in res.fetchall()]\n\n        sent = failed = 0\n        for uid in tg_ids:\n            try:\n                await ctx.bot.send_message(uid, text, parse_mode="Markdown")\n                sent += 1\n            except Exception:\n                failed += 1\n\n        del _admin_state[tg_id]\n        await update.message.reply_text(\n            f"📢 Broadcast complete!\\n✅ Sent: {sent}\\n❌ Failed: {failed}"\n        )\n\n    # ── Add Opportunity flow ───────────────────────────────────────────────\n    elif action == "add_opp":\n        step = state.get("step")\n\n        step_flow = {\n            "title":       ("summary",      "Step 2/6 — Send a short *summary* (1–2 lines):"),\n            "summary":     ("description",  "Step 3/6 — Send the full *description* (or type \'skip\'):"),\n            "description": ("apply_link",   "Step 4/6 — Send the *apply link* (URL):"),\n            "apply_link":  ("deadline",     "Step 5/6 — Send the *deadline* (YYYY-MM-DD) or \'none\':"),\n            "deadline":    ("eligibility",  "Step 6/6 — Send *eligibility* criteria (or \'skip\'):"),\n        }\n\n        state[step] = text if text.lower() != "skip" else None\n\n        if step == "eligibility":\n            # All data collected — AI classify + save\n            await update.message.reply_text("🤖 AI is classifying the opportunity…")\n            title       = state.get("title", "")\n            description = state.get("description") or state.get("summary", "")\n            ai_data     = await classify_opportunity(title, description)\n\n            # Parse deadline\n            raw_deadline = state.get("deadline")\n            parsed_deadline = None\n            if raw_deadline:\n                try:\n                    parsed_deadline = date.fromisoformat(raw_deadline)\n                except ValueError:\n                    pass\n\n            async with get_session() as session:\n                opp = Opportunity(\n                    title               = state["title"],\n                    summary             = state["summary"],\n                    description         = state.get("description"),\n                    apply_link          = state["apply_link"],\n                    deadline            = parsed_deadline,\n                    eligibility         = state.get("eligibility"),\n                    type                = OpportunityType.OTHER,\n                    difficulty          = DifficultyLevel(ai_data.get("difficulty", "intermediate")),\n                    is_beginner_friendly= ai_data.get("is_beginner_friendly", False),\n                    is_low_competition  = ai_data.get("is_low_competition", False),\n                    is_verified         = not ai_data.get("is_scam", False),\n                    tags                = ai_data.get("tags", []),\n                    added_by            = tg_id,\n                )\n                session.add(opp)\n\n            del _admin_state[tg_id]\n            await update.message.reply_text(\n                f"✅ Opportunity added!\\n"\n                f"🤖 AI Classification:\\n"\n                f"• Difficulty: {ai_data.get(\'difficulty\')}\\n"\n                f"• Beginner Friendly: {ai_data.get(\'is_beginner_friendly\')}\\n"\n                f"• Low Competition: {ai_data.get(\'is_low_competition\')}\\n"\n                f"• Tags: {\', \'.join(ai_data.get(\'tags\', []))}\\n"\n                f"• Scam detected: {ai_data.get(\'is_scam\')}"\n            )\n        else:\n            next_step, prompt = step_flow[step]\n            state["step"] = next_step\n            await update.message.reply_text(prompt, parse_mode="Markdown")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Helper sub-views\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def _show_analytics(query) -> None:\n    async with get_session() as session:\n        total_users    = (await session.execute(select(func.count(User.id)))).scalar()\n        premium_users  = (await session.execute(\n            select(func.count(User.id)).where(User.premium_plan != PremiumPlan.FREE)\n        )).scalar()\n        total_events   = (await session.execute(select(func.count(AnalyticsEvent.id)))).scalar()\n\n        # Top events\n        top_events_res = await session.execute(\n            select(AnalyticsEvent.event_name, func.count(AnalyticsEvent.id).label("cnt"))\n            .group_by(AnalyticsEvent.event_name)\n            .order_by(func.count().desc())\n            .limit(5)\n        )\n        top_events = top_events_res.fetchall()\n\n    top_text = "\\n".join(f"  • {e[0]}: {e[1]}" for e in top_events)\n    await query.message.reply_text(\n        f"📊 *Analytics Dashboard*\\n\\n"\n        f"👥 Total Users: *{total_users}*\\n"\n        f"💎 Premium Users: *{premium_users}*\\n"\n        f"🔢 Total Events Tracked: *{total_events}*\\n\\n"\n        f"🔥 *Top Events:*\\n{top_text}",\n        parse_mode="Markdown",\n    )\n\n\nasync def _show_users(query) -> None:\n    async with get_session() as session:\n        res = await session.execute(\n            select(User).order_by(User.created_at.desc()).limit(10)\n        )\n        users = res.scalars().all()\n\n    text = "👥 *Recent Users*\\n\\n"\n    for u in users:\n        plan_emoji = {"free": "🆓", "starter": "⚡", "growth": "🌱", "elite": "💎"}.get(u.premium_plan.value, "")\n        text += f"{plan_emoji} *{u.name}* | {u.college} | Y{u.year} | {u.branch}\\n"\n\n    await query.message.reply_text(text, parse_mode="Markdown")\n', 'handlers/career_assistant.py': '"""\nYuvorai — Career Assistant Chat Handler\nBUG 5 FIX: Chat sessions auto-expire after 2h idle (memory leak prevention)\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom datetime import date, datetime, timedelta\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select\n\nfrom config import settings\nfrom database.db import get_session\nfrom database.models import User, PremiumPlan\nfrom services.ai_engine import career_chat\nfrom services.analytics import track_event\nfrom utils.helpers import require_onboarding\n\nlogger = logging.getLogger(__name__)\n\n# BUG 5 FIX: Store (history, last_active) tuple — auto-cleanup idle sessions\n_chat_sessions: dict[int, dict] = {}\n_SESSION_TTL = timedelta(hours=2)\n\n\ndef _get_history(tg_id: int) -> list:\n    now = datetime.utcnow()\n    # Cleanup expired sessions\n    expired = [k for k, v in _chat_sessions.items()\n               if now - v["last_active"] > _SESSION_TTL]\n    for k in expired:\n        _chat_sessions.pop(k, None)\n\n    if tg_id not in _chat_sessions:\n        _chat_sessions[tg_id] = {"history": [], "last_active": now}\n    _chat_sessions[tg_id]["last_active"] = now\n    return _chat_sessions[tg_id]["history"]\n\n\ndef _set_history(tg_id: int, history: list) -> None:\n    if tg_id in _chat_sessions:\n        _chat_sessions[tg_id]["history"] = history[-20:]\n        _chat_sessions[tg_id]["last_active"] = datetime.utcnow()\n\n\n@require_onboarding\nasync def cmd_ask(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = result.scalar_one_or_none()\n\n    # Reset daily counter if new day\n    today = date.today()\n    if user.ai_messages_reset_date != today:\n        async with get_session() as session:\n            result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            u = result.scalar_one_or_none()\n            if u:\n                u.daily_ai_messages = 0\n                u.ai_messages_reset_date = today\n                u.ai_chat_active = True\n    else:\n        async with get_session() as session:\n            result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            u = result.scalar_one_or_none()\n            if u:\n                u.ai_chat_active = True\n\n    if user.premium_plan == PremiumPlan.FREE and (user.daily_ai_messages or 0) >= settings.MAX_FREE_AI_MESSAGES:\n        kb = InlineKeyboardMarkup([[\n            InlineKeyboardButton("💎 Upgrade for Unlimited Chat", callback_data="prem_view")\n        ]])\n        await update.message.reply_text(\n            f"⚠️ You\'ve used your *{settings.MAX_FREE_AI_MESSAGES} free AI messages* for today.\\n\\n"\n            "Upgrade to *Growth* or *Elite* for unlimited career guidance! 🚀",\n            parse_mode="Markdown",\n            reply_markup=kb,\n        )\n        return\n\n    # If user typed question directly: /ask <question>\n    initial_text = " ".join(ctx.args) if ctx.args else None\n    if initial_text:\n        await _process_message(update, ctx, user, initial_text)\n    else:\n        await update.message.reply_text(\n            "🤖 *AI Career Assistant is ready!*\\n\\n"\n            "Ask me anything:\\n"\n            "• _What should I learn next?_\\n"\n            "• _Best internships for beginners?_\\n"\n            "• _How to crack placements?_\\n"\n            "• _Which skill should I focus on?_\\n\\n"\n            "Just type your question 👇\\n"\n            "Send /endchat when done.",\n            parse_mode="Markdown",\n        )\n    await track_event(tg_id, "ai_chat_started")\n\n\nasync def handle_ai_message(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    text  = update.message.text.strip()\n    if not text:\n        return\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = result.scalar_one_or_none()\n\n    if not user or not user.ai_chat_active:\n        return\n\n    if user.premium_plan == PremiumPlan.FREE and (user.daily_ai_messages or 0) >= settings.MAX_FREE_AI_MESSAGES:\n        kb = InlineKeyboardMarkup([[\n            InlineKeyboardButton("💎 Upgrade Now", callback_data="prem_view")\n        ]])\n        await update.message.reply_text(\n            "⚠️ Daily free message limit reached. Upgrade for unlimited access!",\n            reply_markup=kb,\n        )\n        # Auto end session on limit\n        async with get_session() as session:\n            result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            u = result.scalar_one_or_none()\n            if u:\n                u.ai_chat_active = False\n        return\n\n    await _process_message(update, ctx, user, text)\n\n\nasync def _process_message(\n    update: Update, ctx: ContextTypes.DEFAULT_TYPE, user: User, text: str\n) -> None:\n    tg_id   = user.telegram_id\n    history = _get_history(tg_id)\n\n    await ctx.bot.send_chat_action(chat_id=tg_id, action="typing")\n    reply = await career_chat(user, history, text)\n\n    history.append({"role": "user",      "content": text})\n    history.append({"role": "assistant", "content": reply})\n    _set_history(tg_id, history)\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        u = result.scalar_one_or_none()\n        if u:\n            u.daily_ai_messages = (u.daily_ai_messages or 0) + 1\n\n    await update.message.reply_text(reply, parse_mode="Markdown")\n    await track_event(tg_id, "ai_message_sent")\n\n\nasync def cmd_end_chat(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    _chat_sessions.pop(tg_id, None)\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        u = result.scalar_one_or_none()\n        if u:\n            u.ai_chat_active = False\n\n    await update.message.reply_text(\n        "✅ Chat session ended. Come back anytime with /ask!\\n\\n"\n        "🎯 Use /opportunities to explore new opportunities."\n    )\n', 'handlers/error_handler.py': '"""\nYuvorai — Global Error Handler\nCatches all unhandled exceptions in the Telegram bot.\nLogs them and sends a friendly message to the user.\n"""\n\nfrom __future__ import annotations\n\nimport html\nimport logging\nimport traceback\n\nfrom telegram import Update\nfrom telegram.constants import ParseMode\nfrom telegram.ext import ContextTypes\n\nfrom config import settings\n\nlogger = logging.getLogger(__name__)\n\n\nasync def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:\n    """Log the error and send a friendly message to the user."""\n\n    # Log full traceback\n    logger.error("Exception while handling an update:", exc_info=context.error)\n    tb = "".join(traceback.format_exception(None, context.error, context.error.__traceback__))\n\n    # Notify admins\n    error_msg = (\n        f"⚠️ *Bot Error Detected*\\n\\n"\n        f"```\\n{html.escape(tb[-1500:])}\\n```"\n    )\n    for admin_id in settings.ADMIN_TELEGRAM_IDS:\n        try:\n            await context.bot.send_message(\n                chat_id=admin_id,\n                text=error_msg,\n                parse_mode=ParseMode.MARKDOWN,\n            )\n        except Exception:\n            pass  # Don\'t let error reporting cause more errors\n\n    # Send friendly message to user (if we have a valid update)\n    if isinstance(update, Update) and update.effective_message:\n        try:\n            await update.effective_message.reply_text(\n                "⚠️ Something went wrong on my end.\\n\\n"\n                "Please try again in a moment. If the issue persists, "\n                "contact @YuvoraiSupport 🙏"\n            )\n        except Exception:\n            pass\n', 'handlers/help.py': '"""\nYuvorai — Help Handler + Bot Commands Registration\nSets up /help command and registers all bot commands with Telegram.\n"""\n\nfrom __future__ import annotations\n\nfrom telegram import Update, BotCommand, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes, Application\n\n\n# ── Register bot command list (shows in Telegram menu) ────────────────────────\n\nBOT_COMMANDS = [\n    BotCommand("start",         "🚀 Start Yuvorai / Onboarding"),\n    BotCommand("opportunities", "🔍 Discover personalised opportunities"),\n    BotCommand("ask",           "🤖 Chat with AI career assistant"),\n    BotCommand("pods",          "👥 Join peer communities"),\n    BotCommand("networking",    "🤝 Connect with seniors"),\n    BotCommand("referral",      "🎁 Referral program & rewards"),\n    BotCommand("premium",       "💎 View & upgrade plans"),\n    BotCommand("profile",       "👤 View your profile"),\n    BotCommand("editprofile",   "✏️ Update your profile"),\n    BotCommand("endchat",       "❌ End AI chat session"),\n    BotCommand("help",          "❓ Show all commands"),\n]\n\n\nasync def set_bot_commands(app: Application) -> None:\n    """Call this on startup to register commands in Telegram\'s menu."""\n    await app.bot.set_my_commands(BOT_COMMANDS)\n\n\n# ── /help command ─────────────────────────────────────────────────────────────\n\nasync def cmd_help(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    kb = InlineKeyboardMarkup([\n        [InlineKeyboardButton("🔍 Opportunities",  callback_data="help_opps"),\n         InlineKeyboardButton("🤖 AI Chat",        callback_data="help_ask")],\n        [InlineKeyboardButton("👥 Peer Pods",      callback_data="help_pods"),\n         InlineKeyboardButton("🤝 Networking",     callback_data="help_net")],\n        [InlineKeyboardButton("💎 Premium",        callback_data="help_premium"),\n         InlineKeyboardButton("🎁 Referral",       callback_data="help_ref")],\n    ])\n\n    await update.message.reply_text(\n        "❓ *Yuvorai — All Commands*\\n\\n"\n        "🚀 /start — Set up or reset your profile\\n"\n        "🔍 /opportunities — Get AI-ranked opportunities\\n"\n        "🤖 /ask — Chat with your AI career assistant\\n"\n        "❌ /endchat — End the AI chat session\\n"\n        "👥 /pods — Browse & join peer communities\\n"\n        "🤝 /networking — AI networking templates\\n"\n        "💎 /premium — View plans & upgrade\\n"\n        "🎁 /referral — Invite friends, earn free days\\n"\n        "👤 /profile — View your profile & stats\\n"\n        "✏️ /editprofile — Update your profile\\n"\n        "❓ /help — Show this message\\n\\n"\n        "💡 *Quick Tips:*\\n"\n        "• Use /ask to get personalised career guidance\\n"\n        "• Opportunities are AI-ranked just for you\\n"\n        "• Invite 1 friend → get 7 free Growth days 🎁\\n\\n"\n        "_Yuvorai — Your AI Career Operating System_ 🚀",\n        parse_mode="Markdown",\n        reply_markup=kb,\n    )\n\n\nasync def handle_help_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n\n    tips = {\n        "help_opps": (\n            "🔍 *Opportunities*\\n\\n"\n            "Yuvorai uses AI to rank internships, hackathons, scholarships, and more — "\n            "personalised to your branch, year, interests, and skill level.\\n\\n"\n            "• Free plan: 3 opportunities/day\\n"\n            "• Growth/Elite: unlimited, fully personalised\\n\\n"\n            "Use /opportunities to see today\'s feed."\n        ),\n        "help_ask": (\n            "🤖 *AI Career Assistant*\\n\\n"\n            "Your personal AI mentor. Ask anything:\\n"\n            "• \'What should I learn next?\'\\n"\n            "• \'How do I get an internship at Google?\'\\n"\n            "• \'Review my career plan\'\\n"\n            "• \'Which skills should I focus on?\'\\n\\n"\n            "• Free: 5 messages/day\\n"\n            "• Growth/Elite: unlimited\\n\\n"\n            "Use /ask to start chatting."\n        ),\n        "help_pods": (\n            "👥 *Peer Pods*\\n\\n"\n            "Focused communities of students with the same goals:\\n"\n            "• AI Beginners 🤖\\n"\n            "• Placement Prep 🎯\\n"\n            "• DSA Grind ⚡\\n"\n            "• Startup Builders 🏗️\\n"\n            "• Hackathon Squad 🏆\\n"\n            "• Web Dev Hub 🌐\\n"\n            "• Open Source Crew 🌍\\n"\n            "• Elite Career Circle 💎\\n\\n"\n            "Use /pods to join communities."\n        ),\n        "help_net": (\n            "🤝 *Senior Networking*\\n\\n"\n            "AI-generated, personalised templates to reach out to seniors:\\n"\n            "• LinkedIn DM templates\\n"\n            "• Mentorship request messages\\n"\n            "• Cold email templates\\n"\n            "• Proven networking tips\\n\\n"\n            "Use /networking to get your templates."\n        ),\n        "help_premium": (\n            "💎 *Premium Plans*\\n\\n"\n            "• 🆓 Free — ₹0 (limited access)\\n"\n            "• ⭐ Starter — ₹5/month\\n"\n            "• 🚀 Growth — ₹10/month\\n"\n            "• 💎 Elite — ₹49/month\\n\\n"\n            "Use /premium to compare plans & upgrade."\n        ),\n        "help_ref": (\n            "🎁 *Referral Program*\\n\\n"\n            "Invite friends and earn free premium days!\\n"\n            "• 1 referral = 7 free Growth days\\n"\n            "• 5 referrals = 1 month Growth free\\n"\n            "• 10 referrals = Elite access 30 days\\n\\n"\n            "Use /referral to get your unique link."\n        ),\n    }\n\n    text = tips.get(query.data, "Use /help to see all commands.")\n    await query.message.reply_text(text, parse_mode="Markdown")\n', 'handlers/networking.py': '"""\nYuvorai — Networking Handler\nHelps students connect with seniors using AI-generated message templates.\nBUG FIXED: Added net_back handler, removed dead callback\n"""\n\nfrom __future__ import annotations\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select\n\nfrom database.db import get_session\nfrom database.models import User\nfrom services.ai_engine import generate_networking_template\nfrom services.analytics import track_event\nfrom utils.helpers import require_onboarding\n\n\ndef _networking_menu_kb() -> InlineKeyboardMarkup:\n    return InlineKeyboardMarkup([\n        [InlineKeyboardButton("💼 LinkedIn DM Template",  callback_data="net_linkedin")],\n        [InlineKeyboardButton("🎓 Mentorship Request",    callback_data="net_mentorship")],\n        [InlineKeyboardButton("📧 Cold Email Template",   callback_data="net_cold_email")],\n        [InlineKeyboardButton("💡 Networking Tips",       callback_data="net_tips")],\n    ])\n\n\n@require_onboarding\nasync def cmd_networking(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    await track_event(tg_id, "cmd_networking")\n\n    await update.message.reply_text(\n        "🤝 *Senior Networking System*\\n\\n"\n        "One of the biggest career advantages is knowing the right people.\\n"\n        "Yuvorai gives you AI-crafted, personalised templates so your outreach stands out.\\n\\n"\n        "Choose what you need 👇",\n        parse_mode="Markdown",\n        reply_markup=_networking_menu_kb(),\n    )\n\n\nasync def handle_networking_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n    data  = query.data\n\n    # BUG FIX: handle net_back — go back to main networking menu\n    if data == "net_back":\n        await query.message.reply_text(\n            "🤝 *Senior Networking System*\\n\\nChoose what you need 👇",\n            parse_mode="Markdown",\n            reply_markup=_networking_menu_kb(),\n        )\n        return\n\n    if data == "net_tips":\n        await query.message.reply_text(\n            "💡 *Networking Tips from Yuvorai*\\n\\n"\n            "1️⃣ *Always personalise* — mention their specific work or post\\n"\n            "2️⃣ *Be clear* — say exactly why you\'re reaching out\\n"\n            "3️⃣ *Keep it short* — under 100 words for DMs\\n"\n            "4️⃣ *Don\'t ask for a job* — ask for advice or a 15-min call\\n"\n            "5️⃣ *Follow up once* — after 7 days, politely\\n"\n            "6️⃣ *Engage with their content first* — warm up the connection\\n"\n            "7️⃣ *Add value* — share something relevant to them\\n\\n"\n            "🔑 _The goal of first contact is not a job — it\'s a conversation._",\n            parse_mode="Markdown",\n            reply_markup=InlineKeyboardMarkup([[\n                InlineKeyboardButton("⬅️ Back to Templates", callback_data="net_back")\n            ]]),\n        )\n        return\n\n    type_map = {\n        "net_linkedin":   "linkedin_dm",\n        "net_mentorship": "mentorship_request",\n        "net_cold_email": "cold_email",\n    }\n\n    template_type = type_map.get(data)\n    if not template_type:\n        return\n\n    # Fetch user for personalisation\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = result.scalar_one_or_none()\n\n    if not user:\n        await query.message.reply_text("⚠️ Please complete setup first. Use /start")\n        return\n\n    await query.message.reply_text("✍️ Generating your personalised template…")\n    template = await generate_networking_template(user, template_type)\n\n    label_map = {\n        "linkedin_dm":        "LinkedIn DM",\n        "mentorship_request": "Mentorship Request",\n        "cold_email":         "Cold Email",\n    }\n\n    await query.message.reply_text(\n        f"📝 *Your {label_map[template_type]} Template*\\n\\n"\n        f"```\\n{template}\\n```\\n\\n"\n        "_Customise the details before sending. Good luck! 🚀_",\n        parse_mode="Markdown",\n        reply_markup=InlineKeyboardMarkup([[\n            InlineKeyboardButton("🔄 Generate Another", callback_data=data),\n            InlineKeyboardButton("⬅️ Back",             callback_data="net_back"),\n        ]]),\n    )\n    await track_event(tg_id, "networking_template_generated", {"type": template_type})\n', 'handlers/onboarding.py': '"""\nYuvorai — Onboarding Handler\nBUG FIXES:\n  1. parse_multi_select import added to helpers\n  2. All user strings escaped with safe_md() before MarkdownV2 — no crash on special chars\n  3. Switched welcome-back & final messages to plain Markdown (safer & simpler)\n"""\n\nfrom __future__ import annotations\n\nimport secrets\nimport logging\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import (\n    ContextTypes, ConversationHandler,\n    CommandHandler, MessageHandler, CallbackQueryHandler, filters,\n)\nfrom sqlalchemy import select\n\nfrom database.db import get_session\nfrom database.models import User, SkillLevel\nfrom services.analytics import track_event\nfrom utils.helpers import (\n    build_multi_select_keyboard,\n    INTERESTS_OPTIONS, GOALS_OPTIONS, YEAR_OPTIONS, SKILL_OPTIONS,\n    safe_md,\n)\n\nlogger = logging.getLogger(__name__)\n\nASK_NAME, ASK_COLLEGE, ASK_BRANCH, ASK_YEAR, ASK_INTERESTS, ASK_GOALS, ASK_SKILL, CONFIRM = range(8)\nDONE = ConversationHandler.END\n\n\n# ─────────────────────────────────────────────────────────────────────────────\nasync def cmd_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    tg_id = update.effective_user.id\n\n    async with get_session() as session:\n        result  = await session.execute(select(User).where(User.telegram_id == tg_id))\n        existing = result.scalar_one_or_none()\n\n    if existing and existing.onboarding_complete:\n        # Use plain Markdown — safe for any name\n        await update.message.reply_text(\n            f"👋 Welcome back, *{escape_md(existing.name)}*\\\\!\\n\\n"\n            "Here\'s what you can do:\\n"\n            "🔍 /opportunities — Discover opportunities\\n"\n            "🤖 /ask — AI career assistant\\n"\n            "👥 /pods — Peer communities\\n"\n            "👤 /profile — Your profile\\n"\n            "❓ /help — All commands",\n            parse_mode="Markdown",\n        )\n        return DONE\n\n    if ctx.args:\n        ctx.user_data["referral_code_used"] = ctx.args[0].replace("ref_", "")\n\n    await update.message.reply_text(\n        "🚀 *Welcome to Yuvorai\\\\!*\\n\\n"\n        "_Your AI\\\\-powered career companion for ambitious students\\\\._\\n\\n"\n        "I\'ll help you discover the *right opportunities*, build a *clear roadmap*, "\n        "and connect with *peers & seniors* — all personalised for YOU\\\\.\\n\\n"\n        "Let\'s get you set up in 60 seconds\\\\! 🎯\\n\\n"\n        "First — what\'s your *name*?",\n        parse_mode="MarkdownV2",\n    )\n    return ASK_NAME\n\n\n# ─────────────────────────────────────────────────────────────────────────────\nasync def handle_name(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    name = update.message.text.strip()\n    if len(name) < 2 or len(name) > 64:\n        await update.message.reply_text("⚠️ Please enter a valid name (2–64 characters).")\n        return ASK_NAME\n    ctx.user_data["name"] = name\n    await update.message.reply_text(\n        f"Nice to meet you, *{escape_md(name)}*\\\\! 🎓\\n\\n"\n        "Which *college* are you from? \\\\(Full name is fine\\\\)",\n        parse_mode="MarkdownV2",\n    )\n    return ASK_COLLEGE\n\n\nasync def handle_college(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    ctx.user_data["college"] = update.message.text.strip()\n    await update.message.reply_text(\n        "📚 What\'s your *branch / major*?\\n\\n"\n        "_e\\\\.g\\\\. Computer Science, Electronics, BCA\\\\.\\\\.\\\\._",\n        parse_mode="MarkdownV2",\n    )\n    return ASK_BRANCH\n\n\nasync def handle_branch(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    ctx.user_data["branch"] = update.message.text.strip()\n    keyboard = build_multi_select_keyboard(YEAR_OPTIONS, prefix="year", single=True)\n    await update.message.reply_text(\n        "📅 Which *year* are you in?",\n        reply_markup=InlineKeyboardMarkup(keyboard),\n        parse_mode="Markdown",\n    )\n    return ASK_YEAR\n\n\nasync def handle_year(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    query = update.callback_query\n    await query.answer()\n    ctx.user_data["year"] = int(query.data.replace("year_", ""))\n    ctx.user_data["interests"] = []\n\n    keyboard = build_multi_select_keyboard(INTERESTS_OPTIONS, prefix="int", selected=[])\n    keyboard.append([InlineKeyboardButton("✅ Done", callback_data="int_done")])\n    await query.edit_message_text(\n        "💡 *What are your interests?* \\\\(select all that apply\\\\)\\n\\n_Tap to select, then ✅ Done_",\n        reply_markup=InlineKeyboardMarkup(keyboard),\n        parse_mode="MarkdownV2",\n    )\n    return ASK_INTERESTS\n\n\nasync def handle_interests_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    query = update.callback_query\n    data  = query.data\n\n    if data == "int_done":\n        if not ctx.user_data.get("interests"):\n            await query.answer("⚠️ Please select at least one interest.", show_alert=True)\n            return ASK_INTERESTS\n        await query.answer()\n        ctx.user_data["goals"] = []\n        keyboard = build_multi_select_keyboard(GOALS_OPTIONS, prefix="goal", selected=[])\n        keyboard.append([InlineKeyboardButton("✅ Done", callback_data="goal_done")])\n        await query.edit_message_text(\n            "🎯 *What are your goals?* \\\\(select all that apply\\\\)",\n            reply_markup=InlineKeyboardMarkup(keyboard),\n            parse_mode="MarkdownV2",\n        )\n        return ASK_GOALS\n\n    await query.answer()\n    key = data.replace("int_", "")\n    interests = ctx.user_data.setdefault("interests", [])\n    if key in interests:\n        interests.remove(key)\n    else:\n        interests.append(key)\n\n    keyboard = build_multi_select_keyboard(INTERESTS_OPTIONS, prefix="int", selected=interests)\n    keyboard.append([InlineKeyboardButton("✅ Done", callback_data="int_done")])\n    await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(keyboard))\n    return ASK_INTERESTS\n\n\nasync def handle_goals_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    query = update.callback_query\n    data  = query.data\n\n    if data == "goal_done":\n        if not ctx.user_data.get("goals"):\n            await query.answer("⚠️ Please select at least one goal.", show_alert=True)\n            return ASK_GOALS\n        await query.answer()\n        keyboard = build_multi_select_keyboard(SKILL_OPTIONS, prefix="skill", single=True)\n        await query.edit_message_text(\n            "⚡ *What\'s your current skill level?*",\n            reply_markup=InlineKeyboardMarkup(keyboard),\n            parse_mode="Markdown",\n        )\n        return ASK_SKILL\n\n    await query.answer()\n    key = data.replace("goal_", "")\n    goals = ctx.user_data.setdefault("goals", [])\n    if key in goals:\n        goals.remove(key)\n    else:\n        goals.append(key)\n\n    keyboard = build_multi_select_keyboard(GOALS_OPTIONS, prefix="goal", selected=goals)\n    keyboard.append([InlineKeyboardButton("✅ Done", callback_data="goal_done")])\n    await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(keyboard))\n    return ASK_GOALS\n\n\nasync def handle_skill(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    query = update.callback_query\n    await query.answer()\n    ctx.user_data["skill_level"] = query.data.replace("skill_", "")\n    d = ctx.user_data\n\n    # BUG 2 FIX: Use plain Markdown + escape user strings — safe for any input\n    summary = (\n        f"🎉 *Almost there!* Here\'s your profile:\\n\\n"\n        f"👤 *Name:* {escape_md(d[\'name\'])}\\n"\n        f"🏫 *College:* {escape_md(d[\'college\'])}\\n"\n        f"📚 *Branch:* {escape_md(d[\'branch\'])}\\n"\n        f"📅 *Year:* {d[\'year\']}\\n"\n        f"💡 *Interests:* {escape_md(\', \'.join(d.get(\'interests\', [])))}\\n"\n        f"🎯 *Goals:* {escape_md(\', \'.join(d.get(\'goals\', [])))}\\n"\n        f"⚡ *Skill Level:* {d[\'skill_level\'].capitalize()}\\n\\n"\n        "Is this correct?"\n    )\n    kb = InlineKeyboardMarkup([[\n        InlineKeyboardButton("✅ Looks good!", callback_data="confirm_yes"),\n        InlineKeyboardButton("✏️ Start over",  callback_data="confirm_no"),\n    ]])\n    await query.edit_message_text(summary, parse_mode="Markdown", reply_markup=kb)\n    return CONFIRM\n\n\nasync def handle_confirm(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:\n    query = update.callback_query\n    await query.answer()\n\n    if query.data == "confirm_no":\n        await query.edit_message_text("No problem! Send /start to begin again.")\n        return DONE\n\n    d  = ctx.user_data\n    tg = update.effective_user\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg.id))\n        user   = result.scalar_one_or_none()\n\n        if user:\n            user.name              = d["name"]\n            user.college           = d["college"]\n            user.branch            = d["branch"]\n            user.year              = d["year"]\n            user.interests         = d["interests"]\n            user.goals             = d["goals"]\n            user.skill_level       = SkillLevel(d["skill_level"])\n            user.onboarding_complete = True\n        else:\n            user = User(\n                telegram_id          = tg.id,\n                username             = tg.username,\n                name                 = d["name"],\n                college              = d["college"],\n                branch               = d["branch"],\n                year                 = d["year"],\n                interests            = d["interests"],\n                goals                = d["goals"],\n                skill_level          = SkillLevel(d["skill_level"]),\n                referral_code        = secrets.token_urlsafe(6).upper(),\n                onboarding_complete  = True,\n            )\n            session.add(user)\n            await session.flush()\n\n            ref_code = d.get("referral_code_used")\n            if ref_code:\n                await _process_referral(session, user, ref_code)\n\n    await track_event(tg.id, "onboarding_complete", {"skill": d["skill_level"]})\n\n    await query.edit_message_text(\n        f"🚀 *Welcome to Yuvorai, {escape_md(d[\'name\'])}!*\\n\\n"\n        "Your personalised AI career companion is ready\\\\. 🎉\\n\\n"\n        "Here\'s what you can do:\\n"\n        "🔍 /opportunities — Discover curated opportunities\\n"\n        "🤖 /ask — Chat with AI career assistant\\n"\n        "👥 /pods — Join peer communities\\n"\n        "🤝 /networking — Connect with seniors\\n"\n        "💎 /premium — Unlock full features\\n"\n        "🎁 /referral — Invite friends & earn rewards\\n"\n        "❓ /help — See all commands",\n        parse_mode="Markdown",\n    )\n    return DONE\n\n\nasync def _process_referral(session, new_user: User, ref_code: str) -> None:\n    from database.models import Referral\n    from handlers.referral import grant_referral_reward\n\n    result   = await session.execute(select(User).where(User.referral_code == ref_code))\n    referrer = result.scalar_one_or_none()\n    if referrer and referrer.id != new_user.id:\n        session.add(Referral(\n            referrer_id         = referrer.id,\n            referee_telegram_id = new_user.telegram_id,\n        ))\n        # BUG 8 FIX: pass session directly — no nested session\n        await grant_referral_reward(session, referrer.telegram_id)\n\n\n# Helper — Markdown v1 escape (safe for user strings)\ndef escape_md(text: str) -> str:\n    return re.sub(r"([_*`\\[])", r"\\\\\\1", str(text))\n\n\nimport re\n\n\ndef onboarding_conv_handler() -> ConversationHandler:\n    return ConversationHandler(\n        entry_points=[CommandHandler("start", cmd_start)],\n        states={\n            ASK_NAME:      [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_name)],\n            ASK_COLLEGE:   [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_college)],\n            ASK_BRANCH:    [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_branch)],\n            ASK_YEAR:      [CallbackQueryHandler(handle_year,             pattern=r"^year_")],\n            ASK_INTERESTS: [CallbackQueryHandler(handle_interests_toggle, pattern=r"^int_")],\n            ASK_GOALS:     [CallbackQueryHandler(handle_goals_toggle,     pattern=r"^goal_")],\n            ASK_SKILL:     [CallbackQueryHandler(handle_skill,            pattern=r"^skill_")],\n            CONFIRM:       [CallbackQueryHandler(handle_confirm,          pattern=r"^confirm_")],\n        },\n        fallbacks=[CommandHandler("start", cmd_start)],\n        name="onboarding",\n        persistent=False,\n    )\n', 'handlers/opportunities.py': '"""\nYuvorai — Opportunities Handler\nFetches, ranks, and presents personalized opportunities.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom datetime import date\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select, and_\n\nfrom database.db import get_session\nfrom database.models import Opportunity, User, Application, PremiumPlan\nfrom services.ai_engine import rank_opportunities_for_user\nfrom services.analytics import track_event\nfrom utils.helpers import (\n    require_onboarding, check_premium, escape_md,\n    OPPORTUNITY_TYPE_EMOJI, format_deadline,\n)\n\nlogger = logging.getLogger(__name__)\n\nFREE_LIMIT = 3  # opportunities shown to free users\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# /opportunities command\n# ─────────────────────────────────────────────────────────────────────────────\n\n@require_onboarding\nasync def cmd_opportunities(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    await track_event(tg_id, "cmd_opportunities")\n\n    async with get_session() as session:\n        user_result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = user_result.scalar_one_or_none()\n\n        # Fetch active, verified, non-expired opportunities\n        today = date.today()\n        opp_result = await session.execute(\n            select(Opportunity).where(\n                and_(\n                    Opportunity.is_active == True,\n                    Opportunity.is_verified == True,\n                )\n            ).order_by(Opportunity.created_at.desc()).limit(50)\n        )\n        all_opps = opp_result.scalars().all()\n\n    if not all_opps:\n        await update.message.reply_text(\n            "🔍 No opportunities available right now\\\\. Check back soon — we update daily\\\\!",\n            parse_mode="MarkdownV2",\n        )\n        return\n\n    # AI ranking\n    loading_msg = await update.message.reply_text("🤖 Finding the best matches for you…")\n    ranked = await rank_opportunities_for_user(user, list(all_opps), top_n=20)\n\n    # Plan-based limit\n    is_premium = user.premium_plan != PremiumPlan.FREE\n    display = ranked if is_premium else ranked[:FREE_LIMIT]\n\n    await loading_msg.delete()\n    await _send_opportunity_feed(update, user, display, total_found=len(ranked), is_premium=is_premium)\n\n\nasync def _send_opportunity_feed(\n    update: Update,\n    user: User,\n    opportunities: list[Opportunity],\n    total_found: int,\n    is_premium: bool,\n) -> None:\n    header = (\n        f"🎯 *{len(opportunities)} Personalised Opportunities for You*\\n"\n        f"_Ranked by AI based on your profile_\\n"\n        + ("" if is_premium else f"\\n⚡ _Upgrade to see all {total_found} matches_\\n")\n    )\n    await update.message.reply_text(header, parse_mode="Markdown")\n\n    for opp in opportunities:\n        await _send_opportunity_card(update, opp)\n\n    if not is_premium:\n        kb = [[InlineKeyboardButton("💎 Unlock All Opportunities", callback_data="prem_view")]]\n        await update.message.reply_text(\n            f"_...and {total_found - len(opportunities)} more opportunities waiting for you._",\n            parse_mode="Markdown",\n            reply_markup=InlineKeyboardMarkup(kb),\n        )\n\n\nasync def _send_opportunity_card(update: Update, opp: Opportunity) -> None:\n    emoji = OPPORTUNITY_TYPE_EMOJI.get(opp.type.value, "🔗")\n    badges = []\n    if opp.is_beginner_friendly:\n        badges.append("🟢 Beginner Friendly")\n    if opp.is_low_competition:\n        badges.append("🎯 Low Competition")\n    if opp.is_verified:\n        badges.append("✅ Verified")\n    badge_line = "  ".join(badges)\n\n    deadline_str = format_deadline(opp.deadline)\n    eligibility  = f"\\n👤 *Eligibility:* {opp.eligibility}" if opp.eligibility else ""\n\n    text = (\n        f"{emoji} *{escape_md(opp.title)}*\\n"\n        f"{badge_line}\\n\\n"\n        f"{escape_md(opp.summary)}\\n"\n        f"{eligibility}\\n"\n        f"⏰ *Deadline:* {deadline_str}\\n"\n        f"📊 *Difficulty:* {opp.difficulty.value.capitalize()}"\n    )\n\n    kb = InlineKeyboardMarkup([[\n        InlineKeyboardButton("🚀 Apply Now", url=opp.apply_link),\n        InlineKeyboardButton("📌 Save",      callback_data=f"opp_save_{opp.id}"),\n    ]])\n\n    try:\n        await update.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)\n    except Exception as e:\n        logger.warning(f"Card send error for opp {opp.id}: {e}")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Callback: opp_save_<id>\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def handle_opportunity_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n    data   = query.data  # "opp_save_<id>"\n\n    if data.startswith("opp_save_"):\n        opp_id = int(data.split("_")[-1])\n        async with get_session() as session:\n            user_result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user = user_result.scalar_one_or_none()\n            if user:\n                existing = await session.execute(\n                    select(Application).where(\n                        and_(Application.user_id == user.id, Application.opportunity_id == opp_id)\n                    )\n                )\n                if not existing.scalar_one_or_none():\n                    session.add(Application(user_id=user.id, opportunity_id=opp_id))\n                    await query.answer("📌 Saved to your list!", show_alert=True)\n                    await track_event(tg_id, "opp_saved", {"opp_id": opp_id})\n                else:\n                    await query.answer("Already saved!", show_alert=True)\n', 'handlers/pods.py': '"""\nYuvorai — Peer Pods Handler\nLets students discover, join, and interact with focused communities.\n"""\n\nfrom __future__ import annotations\n\nimport logging\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select, func\n\nfrom database.db import get_session\nfrom database.models import User, Pod, PodMembership, PremiumPlan\nfrom services.analytics import track_event\nfrom utils.helpers import require_onboarding\n\nlogger = logging.getLogger(__name__)\n\nPLAN_ORDER = {PremiumPlan.FREE: 0, PremiumPlan.STARTER: 1, PremiumPlan.GROWTH: 2, PremiumPlan.ELITE: 3}\n\n\n@require_onboarding\nasync def cmd_pods(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    await track_event(tg_id, "cmd_pods")\n\n    async with get_session() as session:\n        user_res = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = user_res.scalar_one_or_none()\n\n        pods_res = await session.execute(\n            select(Pod).where(Pod.is_active == True).order_by(Pod.name)\n        )\n        pods = pods_res.scalars().all()\n\n        # Get user\'s joined pods\n        joined_res = await session.execute(\n            select(PodMembership.pod_id).where(PodMembership.user_id == user.id)\n        )\n        joined_ids = {row[0] for row in joined_res.fetchall()}\n\n    user_plan_rank = PLAN_ORDER.get(user.premium_plan, 0)\n\n    text = "👥 *Yuvorai Peer Pods*\\n_Join focused communities and grow together_\\n\\n"\n    buttons = []\n\n    for pod in pods:\n        required_rank = PLAN_ORDER.get(pod.min_plan, 0)\n        has_access    = user_plan_rank >= required_rank\n        is_joined     = pod.id in joined_ids\n\n        lock   = "" if has_access else f" 🔒 {pod.min_plan.value.capitalize()}"\n        joined = " ✅" if is_joined else ""\n        text  += f"{pod.emoji} *{pod.name}*{lock}{joined}\\n_{pod.description}_\\n\\n"\n\n        if has_access:\n            label = "✅ Joined" if is_joined else f"Join {pod.emoji}"\n            cb    = f"pod_leave_{pod.id}" if is_joined else f"pod_join_{pod.id}"\n        else:\n            label = f"🔒 Upgrade to {pod.min_plan.value.capitalize()}"\n            cb    = "pod_upgrade"\n\n        buttons.append([InlineKeyboardButton(label, callback_data=cb)])\n\n    buttons.append([InlineKeyboardButton("💎 View Plans", callback_data="pod_upgrade")])\n    await update.message.reply_text(text, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(buttons))\n\n\nasync def handle_pods_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n    data  = query.data\n\n    if data == "pod_upgrade":\n        await query.message.reply_text(\n            "💎 Upgrade your plan to unlock premium pods!\\nSend /premium to see plans.",\n        )\n        return\n\n    if data.startswith("pod_join_"):\n        pod_id = int(data.split("_")[-1])\n        async with get_session() as session:\n            user_res = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user = user_res.scalar_one()\n            pod_res  = await session.execute(select(Pod).where(Pod.id == pod_id))\n            pod      = pod_res.scalar_one_or_none()\n\n            if not pod:\n                await query.answer("Pod not found.", show_alert=True)\n                return\n\n            # Check plan access\n            if PLAN_ORDER.get(user.premium_plan, 0) < PLAN_ORDER.get(pod.min_plan, 0):\n                await query.answer(\n                    f"🔒 This pod requires {pod.min_plan.value.capitalize()} plan.", show_alert=True\n                )\n                return\n\n            existing = await session.execute(\n                select(PodMembership).where(\n                    PodMembership.user_id == user.id,\n                    PodMembership.pod_id  == pod_id,\n                )\n            )\n            if not existing.scalar_one_or_none():\n                session.add(PodMembership(user_id=user.id, pod_id=pod_id))\n                pod.member_count = (pod.member_count or 0) + 1\n\n        await track_event(tg_id, "pod_joined", {"pod_id": pod_id})\n        invite_text = f"\\n\\n🔗 [Join the Telegram group]({pod.telegram_invite_link})" if pod.telegram_invite_link else ""\n        await query.message.reply_text(\n            f"🎉 You joined *{pod.name}*!{invite_text}\\n\\n"\n            "Welcome to the community. Stay consistent, support others, and grow together! 💪",\n            parse_mode="Markdown",\n        )\n\n    elif data.startswith("pod_leave_"):\n        pod_id = int(data.split("_")[-1])\n        async with get_session() as session:\n            user_res = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user = user_res.scalar_one()\n            membership = await session.execute(\n                select(PodMembership).where(\n                    PodMembership.user_id == user.id,\n                    PodMembership.pod_id  == pod_id,\n                )\n            )\n            m = membership.scalar_one_or_none()\n            if m:\n                await session.delete(m)\n                # Decrement count\n                pod_res = await session.execute(select(Pod).where(Pod.id == pod_id))\n                pod = pod_res.scalar_one_or_none()\n                if pod and pod.member_count > 0:\n                    pod.member_count -= 1\n\n        await query.answer("You\'ve left the pod.", show_alert=True)\n', 'handlers/premium.py': '"""\nYuvorai — Premium Handler\nDisplays plan comparison and handles upgrade flow.\nBUG FIXED: prem_view callback now sends new message instead of calling cmd_premium\n            (update.message is None inside a callback context)\n"""\n\nfrom __future__ import annotations\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select\n\nfrom database.db import get_session\nfrom database.models import User, PremiumPlan\nfrom services.analytics import track_event\nfrom utils.helpers import require_onboarding\nfrom config import settings\n\n\nPLAN_FEATURES = {\n    PremiumPlan.FREE: {\n        "emoji": "🆓", "label": "Free", "price": "₹0",\n        "features": [\n            "3 opportunity alerts/day",\n            "5 AI messages/day",\n            "Basic pods access",\n        ],\n    },\n    PremiumPlan.STARTER: {\n        "emoji": "⚡", "label": "Starter", "price": f"₹{settings.PRICE_STARTER}/month",\n        "features": [\n            "Daily full opportunity feed",\n            "10 AI messages/day",\n            "All free pods",\n            "Networking tips",\n        ],\n    },\n    PremiumPlan.GROWTH: {\n        "emoji": "🌱", "label": "Growth", "price": f"₹{settings.PRICE_GROWTH}/month",\n        "features": [\n            "Personalised AI recommendations",\n            "Unlimited AI messages",\n            "All pods (DSA, Startup, Open Source)",\n            "AI networking templates",\n            "Deadline reminders",\n        ],\n    },\n    PremiumPlan.ELITE: {\n        "emoji": "💎", "label": "Elite", "price": f"₹{settings.PRICE_ELITE}/month",\n        "features": [\n            "Everything in Growth",\n            "AI career roadmaps",\n            "Resume review",\n            "Accountability circles",\n            "Exclusive Elite community",\n            "Mentorship sessions",\n            "Priority support",\n        ],\n    },\n}\n\n\ndef _build_premium_text(current: PremiumPlan) -> str:\n    text = "💎 *Yuvorai Premium Plans*\\n_Invest in your career — starting at ₹5_\\n\\n"\n    for plan, info in PLAN_FEATURES.items():\n        marker = " ← *Your Plan*" if plan == current else ""\n        text += (\n            f"{info[\'emoji\']} *{info[\'label\']}* — {info[\'price\']}{marker}\\n"\n            + "\\n".join(f"  ✓ {f}" for f in info["features"])\n            + "\\n\\n"\n        )\n    text += "_All plans help you discover better opportunities and grow faster._"\n    return text\n\n\ndef _build_premium_keyboard() -> InlineKeyboardMarkup:\n    return InlineKeyboardMarkup([\n        [InlineKeyboardButton(f"⚡ Get Starter — ₹{settings.PRICE_STARTER}/mo", callback_data="prem_buy_starter")],\n        [InlineKeyboardButton(f"🌱 Get Growth — ₹{settings.PRICE_GROWTH}/mo",  callback_data="prem_buy_growth")],\n        [InlineKeyboardButton(f"💎 Get Elite — ₹{settings.PRICE_ELITE}/mo",    callback_data="prem_buy_elite")],\n        [InlineKeyboardButton("🎁 Earn Free Days (Referral)",                  callback_data="prem_referral")],\n    ])\n\n\n@require_onboarding\nasync def cmd_premium(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    await track_event(tg_id, "cmd_premium")\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = result.scalar_one_or_none()\n\n    text = _build_premium_text(user.premium_plan)\n    await update.message.reply_text(text, parse_mode="Markdown", reply_markup=_build_premium_keyboard())\n\n\nasync def handle_premium_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n    data  = query.data\n\n    # BUG FIX: use query.message.reply_text instead of update.message\n    # (update.message is None inside callback context)\n    if data == "prem_view":\n        async with get_session() as session:\n            result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user: User = result.scalar_one_or_none()\n        text = _build_premium_text(user.premium_plan if user else PremiumPlan.FREE)\n        await query.message.reply_text(text, parse_mode="Markdown", reply_markup=_build_premium_keyboard())\n        return\n\n    if data == "prem_referral":\n        await query.message.reply_text(\n            "🎁 Use /referral to get your unique link and earn free premium days!"\n        )\n        return\n\n    plan_map = {\n        "prem_buy_starter": PremiumPlan.STARTER,\n        "prem_buy_growth":  PremiumPlan.GROWTH,\n        "prem_buy_elite":   PremiumPlan.ELITE,\n    }\n    plan = plan_map.get(data)\n    if not plan:\n        return\n\n    info = PLAN_FEATURES[plan]\n    await query.message.reply_text(\n        f"💳 *Payment for {info[\'emoji\']} {info[\'label\']} Plan*\\n\\n"\n        f"Amount: *{info[\'price\']}*\\n\\n"\n        "To activate your plan, make payment via:\\n"\n        "• UPI: `yuvorai@upi`\\n\\n"\n        "After payment, send the screenshot to @YuvoraiSupport with your plan name.\\n"\n        "Your account will be upgraded within 1 hour. ✅\\n\\n"\n        "_Tip: Refer friends to earn free premium days instead!_",\n        parse_mode="Markdown",\n    )\n    await track_event(tg_id, "premium_intent", {"plan": plan.value})\n', 'handlers/profile.py': '"""\nYuvorai — Profile Handler\nView and update user profile.\n"""\n\nfrom __future__ import annotations\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select, func\n\nfrom database.db import get_session\nfrom database.models import User\nfrom utils.helpers import require_onboarding\n\n\n@require_onboarding\nasync def cmd_profile(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n\n    async with get_session() as session:\n        result = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = result.scalar_one_or_none()\n\n    plan_emoji = {\n        "free": "🆓", "starter": "⚡", "growth": "🌱", "elite": "💎"\n    }.get(user.premium_plan.value, "🆓")\n\n    interests = ", ".join(user.interests) if user.interests else "Not set"\n    goals     = ", ".join(user.goals)     if user.goals     else "Not set"\n\n    expiry_text = ""\n    if user.premium_expires_at and user.premium_plan.value != "free":\n        expiry_text = f"\\n⏳ Plan expires: {user.premium_expires_at.strftime(\'%d %b %Y\')}"\n\n    text = (\n        f"👤 *Your Yuvorai Profile*\\n\\n"\n        f"🧑 Name: *{user.name}*\\n"\n        f"🏫 College: *{user.college}*\\n"\n        f"📚 Branch: *{user.branch}*\\n"\n        f"📅 Year: *{user.year}*\\n"\n        f"⚡ Skill Level: *{user.skill_level.value.capitalize()}*\\n"\n        f"💡 Interests: *{interests}*\\n"\n        f"🎯 Goals: *{goals}*\\n"\n        f"{plan_emoji} Plan: *{user.premium_plan.value.capitalize()}*{expiry_text}\\n"\n        f"🎁 Referral Code: `{user.referral_code}`\\n"\n        f"📅 Joined: {user.created_at.strftime(\'%d %b %Y\') if user.created_at else \'N/A\'}"\n    )\n\n    kb = InlineKeyboardMarkup([\n        [InlineKeyboardButton("✏️ Edit Profile",    callback_data="profile_edit")],\n        [InlineKeyboardButton("💎 Upgrade Plan",    callback_data="prem_view")],\n        [InlineKeyboardButton("🎁 Referral Program",callback_data="ref_view")],\n    ])\n\n    await update.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)\n\n\n@require_onboarding\nasync def cmd_edit_profile(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    await update.message.reply_text(\n        "✏️ To update your profile, use /start to go through the onboarding again.\\n"\n        "Your existing data will be updated. 🔄"\n    )\n', 'handlers/referral.py': '"""\nYuvorai — Referral Handler\nBUG FIXED:\n  1. Referral count query now uses select(func.count(Referral.id)) — was missing table reference\n  2. grant_referral_reward is now called from onboarding after referral saved\n  3. handle_referral_callback now handles ref_view callback properly\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime, timedelta\n\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select, func\n\nfrom config import settings\nfrom database.db import get_session\nfrom database.models import User, Referral, PremiumPlan\nfrom services.analytics import track_event\nfrom utils.helpers import require_onboarding\n\n\n@require_onboarding\nasync def cmd_referral(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    tg_id = update.effective_user.id\n    await track_event(tg_id, "cmd_referral")\n\n    async with get_session() as session:\n        user_res = await session.execute(select(User).where(User.telegram_id == tg_id))\n        user: User = user_res.scalar_one_or_none()\n\n        # BUG FIX: was select(func.count()) — no table ref, always returns 0\n        ref_res = await session.execute(\n            select(func.count(Referral.id)).where(\n                Referral.referrer_id    == user.id,\n                Referral.reward_granted == True,\n            )\n        )\n        total_referrals = ref_res.scalar() or 0\n\n    bot_username   = (await ctx.bot.get_me()).username\n    referral_link  = f"https://t.me/{bot_username}?start=ref_{user.referral_code}"\n    reward_days    = total_referrals * settings.REFERRAL_REWARD_DAYS\n\n    # Milestone rewards text\n    next_milestone = ""\n    if total_referrals < 5:\n        needed = 5 - total_referrals\n        next_milestone = f"\\n🎯 Refer *{needed} more* to unlock 1 month Growth free!"\n    elif total_referrals < 10:\n        needed = 10 - total_referrals\n        next_milestone = f"\\n🎯 Refer *{needed} more* to unlock 30 days Elite!"\n\n    text = (\n        f"🎁 *Referral Program*\\n\\n"\n        f"Invite friends to Yuvorai and *earn free premium days!*\\n\\n"\n        f"🔗 *Your referral link:*\\n`{referral_link}`\\n\\n"\n        f"📊 *Your Stats:*\\n"\n        f"• Total successful referrals: *{total_referrals}*\\n"\n        f"• Total reward days earned: *{reward_days} days*\\n"\n        f"{next_milestone}\\n\\n"\n        f"🏆 *Reward Milestones:*\\n"\n        f"• 1 referral → {settings.REFERRAL_REWARD_DAYS} free Growth days\\n"\n        f"• 5 referrals → 1 month Growth free\\n"\n        f"• 10 referrals → 30 days Elite access\\n\\n"\n        f"_Share with your college friends! 🚀_"\n    )\n\n    kb = InlineKeyboardMarkup([\n        [InlineKeyboardButton("📤 Share Link", switch_inline_query=referral_link)],\n        [InlineKeyboardButton("📊 My Referral Stats", callback_data="ref_stats")],\n    ])\n    await update.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)\n\n\nasync def handle_referral_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:\n    """BUG FIX: was empty — now handles ref_view and ref_stats."""\n    query = update.callback_query\n    await query.answer()\n    tg_id = update.effective_user.id\n    data  = query.data\n\n    if data in ("ref_view", "ref_stats"):\n        async with get_session() as session:\n            user_res = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user: User = user_res.scalar_one_or_none()\n            if not user:\n                return\n\n            all_refs_res = await session.execute(\n                select(func.count(Referral.id)).where(Referral.referrer_id == user.id)\n            )\n            total = all_refs_res.scalar() or 0\n\n            rewarded_res = await session.execute(\n                select(func.count(Referral.id)).where(\n                    Referral.referrer_id    == user.id,\n                    Referral.reward_granted == True,\n                )\n            )\n            rewarded = rewarded_res.scalar() or 0\n            pending  = total - rewarded\n\n        bot_username  = (await ctx.bot.get_me()).username\n        referral_link = f"https://t.me/{bot_username}?start=ref_{user.referral_code}"\n\n        await query.message.reply_text(\n            f"📊 *Your Referral Stats*\\n\\n"\n            f"🔗 Link: `{referral_link}`\\n\\n"\n            f"• Total referrals: *{total}*\\n"\n            f"• Rewards granted: *{rewarded}*\\n"\n            f"• Pending (friend not completed setup): *{pending}*\\n\\n"\n            f"Reward days earned: *{rewarded * settings.REFERRAL_REWARD_DAYS} days* 🎁",\n            parse_mode="Markdown",\n        )\n\n\nasync def grant_referral_reward(session, referrer_telegram_id: int) -> None:\n    """\n    Called from onboarding with the SAME open session — no nested get_session().\n    Grants Growth plan days to the referrer and marks referral as rewarded.\n    """\n    user_res = await session.execute(\n        select(User).where(User.telegram_id == referrer_telegram_id)\n    )\n    referrer: User = user_res.scalar_one_or_none()\n    if not referrer:\n        return\n\n    now            = datetime.utcnow()\n    current_expiry = referrer.premium_expires_at or now\n    new_expiry     = max(current_expiry, now) + timedelta(days=settings.REFERRAL_REWARD_DAYS)\n\n    referrer.premium_expires_at = new_expiry\n    if referrer.premium_plan == PremiumPlan.FREE:\n        referrer.premium_plan = PremiumPlan.GROWTH\n\n    # Mark pending referral as rewarded\n    ref_res = await session.execute(\n        select(Referral).where(\n            Referral.referrer_id    == referrer.id,\n            Referral.reward_granted == False,\n        )\n    )\n    pending = ref_res.scalars().first()\n    if pending:\n        pending.reward_granted = True\n', 'services/__init__.py': '', 'services/ai_engine.py': '"""\nYuvorai — AI Engine\nClassifies, ranks, summarises, and filters opportunities using OpenAI.\nAlso powers the conversational career assistant.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport logging\nfrom datetime import date\nfrom typing import Optional\n\nfrom openai import AsyncOpenAI\n\nfrom config import settings\nfrom database.models import Opportunity, User, DifficultyLevel, SkillLevel\n\nlogger = logging.getLogger(__name__)\nclient = AsyncOpenAI(api_key=settings.OPENAI_API_KEY)\n\n_SKILL_ORDER = {\n    SkillLevel.BEGINNER: 0,\n    SkillLevel.INTERMEDIATE: 1,\n    SkillLevel.ADVANCED: 2,\n}\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Opportunity Ranking / Filtering\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def rank_opportunities_for_user(\n    user: User,\n    opportunities: list[Opportunity],\n    top_n: int = 10,\n) -> list[Opportunity]:\n    """\n    Uses AI to score each opportunity for relevance to the user\'s profile,\n    then returns top_n sorted by score (highest first).\n    Hard-filters out opportunities above the user\'s skill level.\n    """\n    # Hard filter: skill level\n    user_skill_rank = _SKILL_ORDER.get(user.skill_level, 0)\n    filtered = []\n    for opp in opportunities:\n        opp_min_rank = _SKILL_ORDER.get(opp.min_skill_level, 0)\n        if opp_min_rank <= user_skill_rank:\n            filtered.append(opp)\n\n    if not filtered:\n        return []\n\n    # Build scoring prompt\n    opp_list = "\\n".join(\n        f"{i}. [{opp.type.value}] {opp.title} | tags: {opp.tags} | difficulty: {opp.difficulty.value}"\n        for i, opp in enumerate(filtered)\n    )\n\n    prompt = f"""\nYou are a career advisor AI for college students in India.\nScore each opportunity (0-100) for relevance to this student profile.\n\nStudent profile:\n- Branch: {user.branch}\n- Year: {user.year}\n- Interests: {user.interests}\n- Goals: {user.goals}\n- Skill Level: {user.skill_level.value}\n\nOpportunities (index. title | tags | difficulty):\n{opp_list}\n\nReturn a JSON array of objects with keys "index" (int) and "score" (int 0-100).\nPrioritize: relevance to interests/goals > difficulty match > growth potential.\nReturn ONLY the JSON array, no other text.\n"""\n\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=[{"role": "user", "content": prompt}],\n            max_tokens=512,\n            temperature=0.2,\n        )\n        raw = response.choices[0].message.content.strip()\n        scores = json.loads(raw)\n        score_map = {item["index"]: item["score"] for item in scores}\n    except Exception as e:\n        logger.warning(f"AI ranking failed, using default order: {e}")\n        score_map = {i: opp.ai_relevance_score for i, opp in enumerate(filtered)}\n\n    # Sort\n    ranked = sorted(\n        enumerate(filtered),\n        key=lambda t: score_map.get(t[0], 0),\n        reverse=True,\n    )\n    return [opp for _, opp in ranked[:top_n]]\n\n\nasync def summarise_opportunity(description: str) -> str:\n    """Summarise a long opportunity description into 2 concise sentences."""\n    if len(description) < 200:\n        return description\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=[{\n                "role": "user",\n                "content": (\n                    "Summarise this opportunity description in 2 short, clear sentences "\n                    "for a college student. Be direct and highlight key benefits:\\n\\n"\n                    + description\n                ),\n            }],\n            max_tokens=150,\n            temperature=0.3,\n        )\n        return response.choices[0].message.content.strip()\n    except Exception as e:\n        logger.warning(f"Summary failed: {e}")\n        return description[:300] + "…"\n\n\nasync def classify_opportunity(title: str, description: str) -> dict:\n    """\n    Returns: {\n        "is_beginner_friendly": bool,\n        "is_low_competition": bool,\n        "is_scam": bool,\n        "difficulty": "beginner"|"intermediate"|"advanced",\n        "tags": [str, ...]\n    }\n    """\n    prompt = f"""\nClassify this opportunity for college students in India.\nTitle: {title}\nDescription: {description[:500]}\n\nReturn ONLY a JSON object with these keys:\n- is_beginner_friendly (bool): suitable for students with <6 months experience\n- is_low_competition (bool): estimated low applicant pool\n- is_scam (bool): looks fake/fraudulent\n- difficulty ("beginner"/"intermediate"/"advanced")\n- tags (array of strings, max 5 relevant topics)\n"""\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=[{"role": "user", "content": prompt}],\n            max_tokens=200,\n            temperature=0.1,\n        )\n        raw = response.choices[0].message.content.strip()\n        return json.loads(raw)\n    except Exception as e:\n        logger.warning(f"Classification failed: {e}")\n        return {\n            "is_beginner_friendly": False,\n            "is_low_competition": False,\n            "is_scam": False,\n            "difficulty": "intermediate",\n            "tags": [],\n        }\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Career Assistant Chat\n# ─────────────────────────────────────────────────────────────────────────────\n\nSYSTEM_PROMPT = """\nYou are Yuvorai — an AI-powered career companion for ambitious Indian college students.\n\nYour persona:\n- Supportive, motivating, and practically helpful\n- Like a smart senior who genuinely cares about your growth\n- Never generic — always personalized, actionable, direct\n- Use emojis sparingly but effectively\n- Keep responses concise (3–5 sentences max unless explaining a roadmap)\n\nYou help students with:\n- Career clarity and roadmaps\n- Internship and placement advice\n- Skill recommendations\n- Resume and LinkedIn tips\n- Next-step guidance based on their profile\n- Motivation and accountability\n\nAlways be honest. If a student lacks a prerequisite, say so kindly and give them the next step.\nNever overwhelm. One clear action at a time.\n"""\n\n\nasync def career_chat(\n    user: User,\n    conversation_history: list[dict],\n    new_message: str,\n) -> str:\n    """\n    Generates a career assistant reply.\n    conversation_history: list of {"role": "user"/"assistant", "content": str}\n    """\n    # Inject user profile as system context\n    profile_context = (\n        f"\\n\\nStudent profile — "\n        f"Name: {user.name}, Branch: {user.branch}, Year: {user.year}, "\n        f"College: {user.college}, Interests: {user.interests}, "\n        f"Goals: {user.goals}, Skill Level: {user.skill_level.value}, "\n        f"Plan: {user.premium_plan.value}."\n    )\n\n    messages = [\n        {"role": "system", "content": SYSTEM_PROMPT + profile_context},\n        *conversation_history[-10:],  # last 10 messages for context window\n        {"role": "user", "content": new_message},\n    ]\n\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=messages,\n            max_tokens=400,\n            temperature=0.7,\n        )\n        return response.choices[0].message.content.strip()\n    except Exception as e:\n        logger.error(f"Career chat error: {e}")\n        return (\n            "Hmm, I hit a snag there. 🔧 Please try again in a moment. "\n            "If it keeps happening, try /endchat and start fresh!"\n        )\n\n\nasync def generate_networking_template(\n    user: User,\n    template_type: str,  # "linkedin_dm" | "mentorship_request" | "cold_email"\n    target_role: str = "software engineer",\n    target_company: str = "",\n) -> str:\n    """Generate a personalized networking message template."""\n    prompts = {\n        "linkedin_dm": (\n            f"Write a short, genuine LinkedIn connection request message. "\n            f"Sender: {user.name}, a year-{user.year} {user.branch} student at {user.college}. "\n            f"Target: {target_role} {f\'at {target_company}\' if target_company else \'\'}. "\n            f"Interests: {user.interests}. Keep it under 100 words. Avoid generic phrases."\n        ),\n        "mentorship_request": (\n            f"Write a respectful mentorship request message. "\n            f"Sender: {user.name}, {user.branch} year-{user.year} student at {user.college}. "\n            f"Goals: {user.goals}. Target mentor: {target_role}. "\n            f"Make it specific, show genuine curiosity, max 120 words."\n        ),\n        "cold_email": (\n            f"Write a cold email to {target_role} {f\'at {target_company}\' if target_company else \'\'}. "\n            f"From: {user.name}, {user.branch} year-{user.year} at {user.college}. "\n            f"Purpose: internship/career guidance. Interests: {user.interests}. Max 150 words."\n        ),\n    }\n\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=[{"role": "user", "content": prompts.get(template_type, prompts["linkedin_dm"])}],\n            max_tokens=250,\n            temperature=0.7,\n        )\n        return response.choices[0].message.content.strip()\n    except Exception as e:\n        logger.error(f"Template generation error: {e}")\n        return "⚠️ Template generation failed. Please try again."\n\n\nasync def generate_daily_alert_message(user: User, opportunity: Opportunity) -> str:\n    """Generate a personalized, motivating alert message for an opportunity."""\n    days_left = None\n    if opportunity.deadline:\n        delta = (opportunity.deadline - date.today()).days\n        days_left = delta if delta >= 0 else None\n\n    prompt = (\n        f"Write a short (2 sentences max), motivating alert about this opportunity "\n        f"for a student named {user.name} who is interested in {user.interests}.\\n"\n        f"Opportunity: {opportunity.title}\\n"\n        f"Type: {opportunity.type.value}\\n"\n        f"Beginner-friendly: {opportunity.is_beginner_friendly}\\n"\n        f"Low competition: {opportunity.is_low_competition}\\n"\n        f"{\'Days left: \' + str(days_left) if days_left is not None else \'\'}\\n\\n"\n        "Make it feel personal and exciting, not generic. Use 1–2 relevant emojis."\n    )\n\n    try:\n        response = await client.chat.completions.create(\n            model=settings.OPENAI_MODEL,\n            messages=[{"role": "user", "content": prompt}],\n            max_tokens=100,\n            temperature=0.8,\n        )\n        return response.choices[0].message.content.strip()\n    except Exception:\n        return f"🔥 New opportunity for you: *{opportunity.title}*"\n', 'services/alert_service.py': '"""\nYuvorai — Daily Alert Service\nSends personalised daily alerts via BOTH Telegram and WhatsApp.\nUses AI to craft motivating, non-spammy messages.\n"""\n\nfrom __future__ import annotations\n\nimport asyncio\nimport logging\nfrom datetime import date, datetime, timedelta, timezone\n\nfrom telegram import Bot, InlineKeyboardButton, InlineKeyboardMarkup\nfrom sqlalchemy import select, and_\n\nfrom config import settings\nfrom database.db import get_session\nfrom database.models import User, Opportunity, AlertLog, AlertType, PremiumPlan\nfrom services.ai_engine import rank_opportunities_for_user, generate_daily_alert_message\n\nlogger = logging.getLogger(__name__)\n\nIST_OFFSET        = timezone(timedelta(hours=5, minutes=30))\nFREE_ALERT_LIMIT  = 1\nPAID_ALERT_LIMIT  = 3\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Scheduler — runs forever, fires at DAILY_ALERT_HOUR IST\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def schedule_daily_alerts(bot: Bot) -> None:\n    while True:\n        now    = datetime.now(IST_OFFSET)\n        target = now.replace(\n            hour=settings.DAILY_ALERT_HOUR,\n            minute=settings.DAILY_ALERT_MINUTE,\n            second=0, microsecond=0,\n        )\n        if now >= target:\n            target += timedelta(days=1)\n\n        wait = (target - now).total_seconds()\n        logger.info(f"⏰ Next alert in {wait/3600:.1f}h ({target.strftime(\'%H:%M IST\')})")\n        await asyncio.sleep(wait)\n\n        try:\n            await send_daily_alerts(bot)\n        except Exception as e:\n            logger.error(f"Alert run failed: {e}", exc_info=True)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Main sender\n# ─────────────────────────────────────────────────────────────────────────────\n\nasync def send_daily_alerts(bot: Bot) -> None:\n    logger.info("📬 Daily alert run started…")\n\n    async with get_session() as session:\n        users_res = await session.execute(\n            select(User).where(\n                User.is_active          == True,\n                User.alerts_enabled     == True,\n                User.onboarding_complete== True,\n            )\n        )\n        users = users_res.scalars().all()\n\n        opps_res = await session.execute(\n            select(Opportunity).where(\n                Opportunity.is_active   == True,\n                Opportunity.is_verified == True,\n            ).order_by(Opportunity.created_at.desc()).limit(100)\n        )\n        all_opps = opps_res.scalars().all()\n\n    if not all_opps:\n        logger.info("No opportunities to alert about.")\n        return\n\n    total_sent = 0\n    for user in users:\n        try:\n            sent = await _alert_user(bot, user, list(all_opps))\n            total_sent += sent\n        except Exception as e:\n            logger.warning(f"Alert failed for {user.telegram_id}: {e}")\n\n    logger.info(f"✅ Alert run done — {total_sent} alerts to {len(users)} users.")\n\n\nasync def _alert_user(bot: Bot, user: User, all_opps: list[Opportunity]) -> int:\n    # Already alerted IDs\n    async with get_session() as session:\n        done_res = await session.execute(\n            select(AlertLog.reference_id).where(\n                AlertLog.user_id    == user.id,\n                AlertLog.alert_type == AlertType.OPPORTUNITY,\n            ).order_by(AlertLog.sent_at.desc()).limit(50)\n        )\n        alerted_ids = {r[0] for r in done_res.all()}\n\n    candidates = [o for o in all_opps if o.id not in alerted_ids]\n    if not candidates:\n        return 0\n\n    ranked  = await rank_opportunities_for_user(user, candidates, top_n=5)\n    limit   = FREE_ALERT_LIMIT if user.premium_plan == PremiumPlan.FREE else PAID_ALERT_LIMIT\n    to_send = ranked[:limit]\n\n    sent = 0\n    for opp in to_send:\n        # ── Telegram alert ───────────────────────────────────────────────\n        success = await _send_telegram_alert(bot, user, opp)\n\n        if success:\n            async with get_session() as session:\n                session.add(AlertLog(\n                    user_id      = user.id,\n                    alert_type   = AlertType.OPPORTUNITY,\n                    reference_id = opp.id,\n                ))\n            sent += 1\n\n        await asyncio.sleep(0.05)\n\n    # Deadline warnings\n    await _send_deadline_warnings(bot, user, all_opps, alerted_ids)\n    return sent\n\n\nasync def _send_telegram_alert(bot: Bot, user: User, opp: Opportunity) -> bool:\n    from utils.helpers import format_deadline\n    try:\n        msg = await generate_daily_alert_message(user, opp)\n        text = (\n            f"🔔 *Daily Opportunity Alert*\\n\\n"\n            f"{msg}\\n\\n"\n            f"*{opp.title}*\\n"\n            f"⏰ {format_deadline(opp.deadline)}\\n"\n            f"📊 {opp.difficulty.value.capitalize()} level"\n        )\n        kb = InlineKeyboardMarkup([[\n            InlineKeyboardButton("🚀 Apply Now",  url=opp.apply_link),\n            InlineKeyboardButton("📋 More Opps", callback_data="opp_browse"),\n        ]])\n        await bot.send_message(\n            chat_id=user.telegram_id,\n            text=text,\n            parse_mode="Markdown",\n            reply_markup=kb,\n        )\n        return True\n    except Exception as e:\n        logger.warning(f"Telegram alert failed for {user.telegram_id}: {e}")\n        return False\n\n\n        msg = await generate_daily_alert_message(user, opp)\n        text = (\n            f"🔔 *Daily Alert from Yuvorai*\\n\\n"\n            f"{msg}\\n\\n"\n            f"{fmt_opportunity(opp)}\\n\\n"\n            f"_Reply \'menu\' to see all options_"\n        )\n        await wa_client.send_text(str(user.telegram_id), text)\n    except Exception as e:\n        logger.debug(f"WhatsApp alert skipped for {user.telegram_id}: {e}")\n\n\nasync def _send_deadline_warnings(\n    bot: Bot, user: User, all_opps: list, alerted_ids: set\n) -> None:\n    """Warn about opportunities closing today."""\n    today  = date.today()\n    urgent = [\n        o for o in all_opps\n        if o.deadline and o.deadline == today and o.id not in alerted_ids\n    ]\n    for opp in urgent[:2]:\n        try:\n            await bot.send_message(\n                chat_id=user.telegram_id,\n                text=(\n                    f"⏰ *Deadline TODAY!*\\n\\n"\n                    f"*{opp.title}* closes in hours.\\n"\n                    f"Don\'t miss it — apply now! 🎯"\n                ),\n                parse_mode="Markdown",\n                reply_markup=InlineKeyboardMarkup([[\n                    InlineKeyboardButton("🚀 Apply Now", url=opp.apply_link)\n                ]]),\n            )\n        except Exception:\n            pass\n', 'services/analytics.py': '"""\nYuvorai — Analytics Service\nLightweight event tracker stored in PostgreSQL/SQLite.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom typing import Optional\n\nfrom database.db import get_session\nfrom database.models import AnalyticsEvent\n\nlogger = logging.getLogger(__name__)\n\n\nasync def track_event(\n    telegram_id: int,\n    event_name: str,\n    event_data: Optional[dict] = None,\n) -> None:\n    """\n    Fire-and-forget event tracking. Never raises — analytics must never\n    break the main user flow.\n    """\n    try:\n        async with get_session() as session:\n            session.add(AnalyticsEvent(\n                telegram_id = telegram_id,\n                event_name  = event_name,\n                event_data  = event_data or {},\n            ))\n    except Exception as e:\n        logger.warning(f"Analytics track_event failed silently: {e}")\n', 'utils/__init__.py': '', 'utils/helpers.py': '"""\nYuvorai — Helper Utilities\nShared constants, keyboard builders, decorators, and formatters.\n"""\n\nfrom __future__ import annotations\n\nimport functools\nimport re\nfrom datetime import date\nfrom typing import Optional\n\nfrom telegram import Update, InlineKeyboardButton\nfrom telegram.ext import ContextTypes\nfrom sqlalchemy import select\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Constants\n# ─────────────────────────────────────────────────────────────────────────────\n\nINTERESTS_OPTIONS = [\n    "AI / ML", "Web Dev", "App Dev", "Cybersecurity",\n    "DSA", "Design", "Startups", "Placements",\n    "Blockchain", "Cloud", "Data Science", "Game Dev",\n]\n\nGOALS_OPTIONS = [\n    "Internships", "Placements", "Freelancing",\n    "Open Source", "Startup Building", "Hackathons",\n    "Research", "Higher Studies",\n]\n\nYEAR_OPTIONS = [\n    ("1st Year", "1"),\n    ("2nd Year", "2"),\n    ("3rd Year", "3"),\n    ("4th Year", "4"),\n    ("5th Year / PG", "5"),\n]\n\nSKILL_OPTIONS = [\n    ("🌱 Beginner",     "beginner"),\n    ("⚡ Intermediate", "intermediate"),\n    ("🔥 Advanced",     "advanced"),\n]\n\nOPPORTUNITY_TYPE_EMOJI = {\n    "internship":  "💼",\n    "hackathon":   "🏆",\n    "contest":     "🏅",\n    "scholarship": "🎓",\n    "open_source": "🌍",\n    "startup":     "🚀",\n    "placement":   "🏢",\n    "other":       "🔗",\n}\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Keyboard builders\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef build_multi_select_keyboard(\n    options: list,\n    prefix: str,\n    selected: Optional[list] = None,\n    single: bool = False,\n    columns: int = 2,\n) -> list[list[InlineKeyboardButton]]:\n    if selected is None:\n        selected = []\n    rows: list[list[InlineKeyboardButton]] = []\n    row:  list[InlineKeyboardButton]       = []\n    for opt in options:\n        label, value = opt if isinstance(opt, tuple) else (opt, opt)\n        is_sel  = (not single) and (value in selected)\n        display = f"✅ {label}" if is_sel else label\n        row.append(InlineKeyboardButton(display, callback_data=f"{prefix}_{value}"))\n        if len(row) == columns:\n            rows.append(row)\n            row = []\n    if row:\n        rows.append(row)\n    return rows\n\n\n# BUG 1 FIX: parse_multi_select was imported in onboarding but never defined\ndef parse_multi_select(selected_keys: list, options: list) -> list[str]:\n    """Return display labels for selected option keys."""\n    mapping = {}\n    for opt in options:\n        if isinstance(opt, tuple):\n            label, value = opt\n        else:\n            label = value = opt\n        mapping[value] = label\n    return [mapping[k] for k in selected_keys if k in mapping]\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Decorators\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef require_onboarding(func):\n    """Redirect to /start if user hasn\'t completed onboarding."""\n    @functools.wraps(func)\n    async def wrapper(update: Update, ctx: ContextTypes.DEFAULT_TYPE, *args, **kwargs):\n        from database.db import get_session\n        from database.models import User\n        tg_id = update.effective_user.id\n        async with get_session() as session:\n            result = await session.execute(select(User).where(User.telegram_id == tg_id))\n            user = result.scalar_one_or_none()\n        if not user or not user.onboarding_complete:\n            await update.message.reply_text(\n                "👋 Hey! Let\'s get you set up first.\\n\\n"\n                "Send /start to begin your Yuvorai journey! 🚀"\n            )\n            return\n        return await func(update, ctx, *args, **kwargs)\n    return wrapper\n\n\ndef check_premium(user, min_plan: str = "starter") -> bool:\n    plan_order = {"free": 0, "starter": 1, "growth": 2, "elite": 3}\n    return plan_order.get(user.premium_plan.value, 0) >= plan_order.get(min_plan, 1)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# Text formatters\n# ─────────────────────────────────────────────────────────────────────────────\n\n# BUG 2 FIX: safe_md escapes ALL MarkdownV2 special characters in user-supplied strings\ndef safe_md(text: str) -> str:\n    """Escape all MarkdownV2 special characters in user-supplied text."""\n    special = r"\\_*[]()~`>#+-=|{}.!"\n    return re.sub(f"([{re.escape(special)}])", r"\\\\\\1", str(text))\n\n\ndef escape_md(text: str) -> str:\n    """Escape Telegram Markdown v1 special characters (for parse_mode=\'Markdown\')."""\n    return re.sub(r"([_*`\\[])", r"\\\\\\1", str(text))\n\n\ndef format_deadline(deadline: Optional[date]) -> str:\n    if not deadline:\n        return "Open / Rolling"\n    delta = (deadline - date.today()).days\n    if delta < 0:\n        return f"🔴 Expired ({deadline.strftime(\'%d %b %Y\')})"\n    if delta == 0:\n        return "🔴 TODAY — Apply now!"\n    if delta <= 3:\n        return f"🔴 {deadline.strftime(\'%d %b %Y\')} ({delta}d left!)"\n    if delta <= 7:\n        return f"🟡 {deadline.strftime(\'%d %b %Y\')} ({delta} days left)"\n    return f"🟢 {deadline.strftime(\'%d %b %Y\')} ({delta} days left)"\n\n\ndef truncate(text: str, max_len: int = 200) -> str:\n    if len(text) <= max_len:\n        return text\n    return text[:max_len].rstrip() + "…"\n'}

def main():
    print("=" * 50)
    print("YUVORAI — Creating project files")
    print("=" * 50)

    # Step 1: Create all files
    for rel_path, content in FILES.items():
        dir_name = os.path.dirname(rel_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        with open(rel_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"  created: {rel_path}")

    print(f"\n✅ All files created!")

    # Step 2: Install requirements (always, not just on Render)
    print("\n📦 Installing requirements...")
    req_path = os.path.join(os.getcwd(), "requirements.txt")
    if os.path.exists(req_path):
        result = subprocess.run(
            [sys.executable, "-m", "pip", "install", "-r", req_path, "--quiet"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
        if result.returncode == 0:
            print("✅ Requirements installed!")
        else:
            print("⚠️  pip output:")
            print(result.stderr.decode())
    else:
        print("❌ requirements.txt not found!")
        sys.exit(1)

    print("\n🚀 Setup complete! Bot is ready.")

if __name__ == "__main__":
    main()
